export const losungen2026: Record<string, DailyLosung> = {"2026-01-01":{"text":"Der HERR wird aufheben die Schmach seines Volks in allen Landen.","reference":"Jesaja 25,8","translation":"Losung","lehrtext":"Darin ist erschienen die Liebe Gottes unter uns, dass Gott seinen eingebornen Sohn gesandt hat in die Welt, damit wir durch ihn leben sollen.","lehrtextReference":"1. Johannes 4,9"},"2026-01-02":{"text":"Der HERR segnet, die ihn fürchten, die Kleinen und die Großen.","reference":"Psalm 115,13","translation":"Losung","lehrtext":"Vergeltet nicht Böses mit Bösem oder Scheltwort mit Scheltwort, sondern segnet vielmehr, weil ihr dazu berufen seid, auf dass ihr Segen erbt.","lehrtextReference":"1. Petrus 3,9"},"2026-01-03":{"text":"HERR, deine Augen, sind sie nicht auf Treue gerichtet?","reference":"Jeremia 5,3","translation":"Losung","lehrtext":"Mein Lieber, du handelst treu in dem, was du an den Brüdern tust, zumal an fremden.","lehrtextReference":"3. Johannes 1,5"},"2026-01-04":{"text":"Ich harrte des HERRN, und er neigte sich zu mir und hörte mein Schreien.","reference":"Psalm 40,2","translation":"Losung","lehrtext":"Der Kranke antwortete Jesus: Herr, ich habe keinen Menschen, der mich in den Teich bringt, wenn das Wasser sich bewegt; wenn ich aber hinkomme, so steigt ein anderer vor mir hinein. Jesus spricht zu ihm: Steh auf, nimm dein Bett und geh hin!","lehrtextReference":"Johannes 5,7-8"},"2026-01-05":{"text":"Der HERR ist seines Volkes Stärke.","reference":"Psalm 28,8","translation":"Losung","lehrtext":"Er aber, unser Herr Jesus Christus, und Gott, unser Vater, der uns geliebt und uns einen ewigen Trost gegeben hat und eine gute Hoffnung durch Gnade, der tröste eure Herzen und stärke euch in allem guten Werk und Wort.","lehrtextReference":"2. Thessalonicher 2,16-17"},"2026-01-06":{"text":"Du herrschest über das ungestüme Meer, du stillest seine Wellen, wenn sie sich erheben.","reference":"Psalm 89,10","translation":"Losung","lehrtext":"Jesus sagt zu den Jüngern: Ihr Kleingläubigen, warum seid ihr so furchtsam?, und stand auf und bedrohte den Wind und das Meer; und es ward eine große Stille.","lehrtextReference":"Matthäus 8,26"},"2026-01-07":{"text":"So kehrt nun um von euren bösen Wegen. Warum wollt ihr sterben?","reference":"Hesekiel 33,11","translation":"Losung","lehrtext":"Wer die Wahrheit tut, der kommt zu dem Licht, damit offenbar wird, dass seine Werke in Gott getan sind.","lehrtextReference":"Johannes 3,21"},"2026-01-08":{"text":"HERR, du hast angefangen, deinem Knecht zu offenbaren deine Herrlichkeit und deine starke Hand.","reference":"5. Mose 3,24","translation":"Losung","lehrtext":"/Jesus betete:/ Vater, ich will, dass, wo ich bin, auch die bei mir seien, die du mir gegeben hast, damit sie meine Herrlichkeit sehen, die du mir gegeben hast.","lehrtextReference":"Johannes 17,24"},"2026-01-09":{"text":"Ich will sie trösten und sie erfreuen nach ihrer Betrübnis.","reference":"Jeremia 31,13","translation":"Losung","lehrtext":"Unsre Hoffnung steht fest für euch, weil wir wissen: Wie ihr an den Leiden teilhabt, so habt ihr auch am Trost teil.","lehrtextReference":"2. Korinther 1,7"},"2026-01-10":{"text":"Das sei ferne von uns, dass wir uns auflehnen gegen den HERRN und uns heute von ihm abwenden.","reference":"Josua 22,29","translation":"Losung","lehrtext":"Hab acht auf dich selbst und auf die Lehre; beharre in diesen Stücken! Denn wenn du das tust, wirst du dich selbst retten und die, die dich hören.","lehrtextReference":"1. Timotheus 4,16"},"2026-01-11":{"text":"Gott, der HERR, der Mächtige, redet und ruft der Welt zu vom Aufgang der Sonne bis zu ihrem Niedergang.","reference":"Psalm 50,1","translation":"Losung","lehrtext":"Gehet hin in alle Welt und predigt das Evangelium aller Kreatur.","lehrtextReference":"Markus 16,15"},"2026-01-12":{"text":"HERR, es ist dir nicht schwer, dem Schwachen gegen den Starken zu helfen.","reference":"2. Chronik 14,10","translation":"Losung","lehrtext":"Jesus bedrohte den unreinen Geist und machte den Knaben gesund und gab ihn seinem Vater wieder.","lehrtextReference":"Lukas 9,42"},"2026-01-13":{"text":"/Der HERR spricht:/ Wer mich ehrt, den will ich auch ehren; wer aber mich verachtet, der soll wieder verachtet werden.","reference":"1. Samuel 2,30","translation":"Losung","lehrtext":"/Jesus sprach:/ Wer mich liebt, der wird mein Wort halten; und mein Vater wird ihn lieben, und wir werden zu ihm kommen und Wohnung bei ihm nehmen.","lehrtextReference":"Johannes 14,23"},"2026-01-14":{"text":"Der Engel des HERRN lagert sich um die her, die ihn fürchten, und hilft ihnen heraus.","reference":"Psalm 34,8","translation":"Losung","lehrtext":"Der Engel des Herrn tat in der Nacht die Türen des Gefängnisses auf und führte die Apostel heraus und sprach: Geht hin und tretet im Tempel auf und redet zum Volk alle Worte dieses Lebens.","lehrtextReference":"Apostelgeschichte 5,19-20"},"2026-01-15":{"text":"Kommt herzu, lasst uns dem HERRN frohlocken und jauchzen dem Hort unsres Heils!","reference":"Psalm 95,1","translation":"Losung","lehrtext":"Ja, alle Völker werden kommen und anbeten vor dir, denn deine Urteile sind offenbar geworden.","lehrtextReference":"Offenbarung 15,4"},"2026-01-16":{"text":"Wir wollen mit euch gehen, denn wir haben gehört, dass Gott mit euch ist.","reference":"Sacharja 8,23","translation":"Losung","lehrtext":"Wir sind durch einen Geist alle zu einem Leib getauft, wir seien Juden oder Griechen, Sklaven oder Freie, und sind alle mit einem Geist getränkt.","lehrtextReference":"1. Korinther 12,13"},"2026-01-17":{"text":"Der HERR ist deine Zuversicht.","reference":"Psalm 91,9","translation":"Losung","lehrtext":"Als Bartimäus hörte, dass es Jesus von Nazareth war, fing er an zu schreien und zu sagen: Jesus, du Sohn Davids, erbarme dich meiner!","lehrtextReference":"Markus 10,47"},"2026-01-18":{"text":"/Der HERR spricht:/ Frieden mache ich zu deiner Wache und Gerechtigkeit zu deiner Obrigkeit.","reference":"Jesaja 60,17","translation":"Losung","lehrtext":"Es wird mit uns sein Gnade, Barmherzigkeit und Friede von Gott, dem Vater, und von Jesus Christus, dem Sohn des Vaters, in Wahrheit und Liebe.","lehrtextReference":"2. Johannes 1,3"},"2026-01-19":{"text":"Frage doch zuerst nach dem Wort des HERRN!","reference":"2. Chronik 18,4","translation":"Losung","lehrtext":"/Jesus spricht:/ Die Worte, die ich zu euch geredet habe, die sind Geist und sind Leben.","lehrtextReference":"Johannes 6,63"},"2026-01-20":{"text":"Wo Träume sich mehren und Nichtigkeiten und viele Worte, da fürchte Gott!","reference":"Prediger 5,6","translation":"Losung","lehrtext":"Wir sind nicht ausgeklügelten Fabeln gefolgt, als wir euch kundgetan haben die Kraft und das Kommen unseres Herrn Jesus Christus; sondern wir haben seine Herrlichkeit mit eigenen Augen gesehen.","lehrtextReference":"2. Petrus 1,16"},"2026-01-21":{"text":"Meine Seele dürstet nach Gott, nach dem lebendigen Gott. Wann werde ich dahin kommen, dass ich Gottes Angesicht schaue?","reference":"Psalm 42,3","translation":"Losung","lehrtext":"So sind wir denn allezeit getrost und wissen: Solange wir im Leibe wohnen, weilen wir fern von dem Herrn; denn wir wandeln im Glauben und nicht im Schauen.","lehrtextReference":"2. Korinther 5,6-7"},"2026-01-22":{"text":"Die er aus den Ländern zusammengebracht hat von Osten und Westen, von Norden und Süden: Die sollen dem HERRN danken für seine Güte und für seine Wunder, die er an den Menschenkindern tut.","reference":"Psalm 107,3.8","translation":"Losung","lehrtext":"Ihr hattet keine Hoffnung und wart ohne Gott in der Welt. Jetzt aber in Christus Jesus seid ihr, die ihr einst fern wart, nahe geworden durch das Blut Christi.","lehrtextReference":"Epheser 2,12-13"},"2026-01-23":{"text":"Der HERR wird König sein immer und ewig.","reference":"2. Mose 15,18","translation":"Losung","lehrtext":"Jesus wird König sein über das Haus Jakob in Ewigkeit, und seine Herrschaft wird kein Ende haben.","lehrtextReference":"Lukas 1,33"},"2026-01-24":{"text":"Ihre Gemeinde soll vor mir fest gegründet stehen.","reference":"Jeremia 30,20","translation":"Losung","lehrtext":"Ihr seid erbaut auf den Grund der Apostel und Propheten, da Jesus Christus der Eckstein ist.","lehrtextReference":"Epheser 2,20"},"2026-01-25":{"text":"Ich habe die Erde gemacht und Menschen und Tiere, die auf Erden sind, durch meine große Kraft und meinen ausgereckten Arm und gebe sie, wem ich will.","reference":"Jeremia 27,5","translation":"Losung","lehrtext":"Gottes unsichtbares Wesen – das ist seine ewige Kraft und Gottheit – wird seit der Schöpfung der Welt, wenn man es mit Vernunft wahrnimmt, an seinen Werken ersehen.","lehrtextReference":"Römer 1,20"},"2026-01-26":{"text":"Gott ändert Zeit und Stunde; er setzt Könige ab und setzt Könige ein.","reference":"Daniel 2,21","translation":"Losung","lehrtext":"Insbesondere bitte ich euch nun, vor Gott einzutreten für alle Menschen in Bitte, Gebet, Fürbitte und Danksagung, für die Könige und alle Amtsträger.","lehrtextReference":"1. Timotheus 2,1-2"},"2026-01-27":{"text":"Meine Gedanken sind nicht eure Gedanken, und eure Wege sind nicht meine Wege, spricht der HERR.","reference":"Jesaja 55,8","translation":"Losung","lehrtext":"Wohlan, die ihr sagt: Heute oder morgen werden wir in die und die Stadt aufbrechen, ein Jahr dort verbringen, gute Geschäfte machen und Gewinne erzielen! Ihr solltet sagen: Wenn der Herr es will, werden wir leben und dies oder jenes tun.","lehrtextReference":"Jakobus 4,13.15"},"2026-01-28":{"text":"Verlass mich nicht, HERR, mein Gott, sei nicht ferne von mir!","reference":"Psalm 38,22","translation":"Losung","lehrtext":"Jaïrus bat Jesus sehr und sprach: Meine Tochter liegt in den letzten Zügen; komm und lege ihr die Hände auf, dass sie gesund werde und lebe.","lehrtextReference":"Markus 5,23"},"2026-01-29":{"text":"HERR, mein Gott, groß sind deine Wunder und deine Gedanken, die du an uns beweisest; dir ist nichts gleich!","reference":"Psalm 40,6","translation":"Losung","lehrtext":"Der Geheilte stand auf und nahm sogleich sein Bett und ging hinaus vor aller Augen, sodass sie sich alle entsetzten und Gott priesen und sprachen: Wir haben solches noch nie gesehen.","lehrtextReference":"Markus 2,12"},"2026-01-30":{"text":"/Der HERR sprach zu seinem Volk:/ Siehe, ich will euch Getreide, Wein und Öl die Fülle schicken, dass ihr genug daran haben sollt.","reference":"Joel 2,19","translation":"Losung","lehrtext":"Jesus nahm die fünf Brote und zwei Fische und sah auf zum Himmel, dankte und brach die Brote und gab sie den Jüngern, dass sie sie ihnen austeilten, und die zwei Fische teilte er unter sie alle. Und sie aßen alle und wurden satt.","lehrtextReference":"Markus 6,41-42"},"2026-01-31":{"text":"HERR, du lässest mich fröhlich singen von deinen Werken, und ich rühme die Taten deiner Hände.","reference":"Psalm 92,5","translation":"Losung","lehrtext":"Der Gelähmte sprang auf, konnte stehen und gehen und ging mit ihnen in den Tempel, lief und sprang umher und lobte Gott.","lehrtextReference":"Apostelgeschichte 3,8"},"2026-02-01":{"text":"Eure Liebe ist wie der Tau, der frühmorgens vergeht!","reference":"Hosea 6,4","translation":"Losung","lehrtext":"/Jesus spricht:/ Bleibt in meiner Liebe!","lehrtextReference":"Johannes 15,9"},"2026-02-02":{"text":"Die Israeliten schrien zu dem HERRN, und der HERR erweckte ihnen einen Retter, der sie errettete.","reference":"Richter 3,9","translation":"Losung","lehrtext":"Werft euer Vertrauen nicht weg, welches eine große Belohnung hat.","lehrtextReference":"Hebräer 10,35"},"2026-02-03":{"text":"Wer den Armen verspottet, verhöhnt dessen Schöpfer; und wer sich über eines andern Unglück freut, wird nicht ungestraft bleiben.","reference":"Sprüche 17,5","translation":"Losung","lehrtext":"Hat nicht Gott erwählt die Armen in der Welt, die im Glauben reich sind und Erben des Reichs, das er verheißen hat denen, die ihn lieb haben?","lehrtextReference":"Jakobus 2,5"},"2026-02-04":{"text":"Wessen Zuversicht der HERR ist, der ist wie ein Baum, am Wasser gepflanzt, der seine Wurzeln zum Bach hin streckt. Er sorgt sich nicht, wenn ein dürres Jahr kommt, sondern bringt ohne Aufhören Früchte.","reference":"Jeremia 17,7.8","translation":"Losung","lehrtext":"/Jesus spricht:/ Ich bin der Weinstock, ihr seid die Reben. Wer in mir bleibt und ich in ihm, der bringt viel Frucht.","lehrtextReference":"Johannes 15,5"},"2026-02-05":{"text":"Bewahre mich, Gott; denn ich traue auf dich.","reference":"Psalm 16,1","translation":"Losung","lehrtext":"Der Herr ist treu; der wird euch stärken und bewahren vor dem Bösen.","lehrtextReference":"2. Thessalonicher 3,3"},"2026-02-06":{"text":"Du, Herr, bist gerecht, wir aber müssen uns alle heute schämen.","reference":"Daniel 9,7","translation":"Losung","lehrtext":"Der König wird ihnen antworten und sagen: Wahrlich, ich sage euch: Was ihr nicht getan habt einem von diesen Geringsten, das habt ihr mir auch nicht getan.","lehrtextReference":"Matthäus 25,45"},"2026-02-07":{"text":"Seine Herrschaft wird groß und des Friedens kein Ende sein.","reference":"Jesaja 9,6","translation":"Losung","lehrtext":"Christus ist unser Friede.","lehrtextReference":"Epheser 2,14"},"2026-02-08":{"text":"Der HERR hat Großes an uns getan; des sind wir fröhlich.","reference":"Psalm 126,3","translation":"Losung","lehrtext":"Sie waren täglich einmütig beieinander im Tempel und brachen das Brot hier und dort in den Häusern, hielten die Mahlzeiten mit Freude und lauterem Herzen und lobten Gott und fanden Wohlwollen beim ganzen Volk.","lehrtextReference":"Apostelgeschichte 2,46-47"},"2026-02-09":{"text":"Wenn ein Fremdling bei euch wohnt in eurem Lande, den sollt ihr nicht bedrücken.","reference":"3. Mose 19,33","translation":"Losung","lehrtext":"/Jesus spricht:/ Ihr seid meine Freunde, wenn ihr tut, was ich euch gebiete.","lehrtextReference":"Johannes 15,14"},"2026-02-10":{"text":"/Jakob sprach:/ HERR, ich bin zu gering aller Barmherzigkeit und aller Treue, die du an deinem Knechte getan hast.","reference":"1. Mose 32,11","translation":"Losung","lehrtext":"/Paulus schreibt:/ Mir ist Barmherzigkeit widerfahren, dass Christus Jesus an mir als Erstem alle Geduld erweise, zum Vorbild denen, die an ihn glauben sollten zum ewigen Leben.","lehrtextReference":"1. Timotheus 1,16"},"2026-02-11":{"text":"Ist nicht Ephraim mein teurer Sohn und mein liebes Kind? Denn sooft ich ihm auch drohe, muss ich doch seiner gedenken; darum bricht mir mein Herz, dass ich mich seiner erbarmen muss, spricht der HERR.","reference":"Jeremia 31,20","translation":"Losung","lehrtext":"Gott hat sein Volk nicht verstoßen, das er zuvor erwählt hat.","lehrtextReference":"Römer 11,2"},"2026-02-12":{"text":"Ich tilge deine Missetat wie eine Wolke und deine Sünden wie den Nebel. Kehre dich zu mir, denn ich erlöse dich!","reference":"Jesaja 44,22","translation":"Losung","lehrtext":"Ihr wisst, dass Jesus Christus erschienen ist, damit er die Sünden wegnehme, und in ihm ist keine Sünde.","lehrtextReference":"1. Johannes 3,5"},"2026-02-13":{"text":"Werdet ihr der Stimme des HERRN nicht gehorchen, so wird die Hand des HERRN gegen euch sein wie gegen eure Väter.","reference":"1. Samuel 12,15","translation":"Losung","lehrtext":"Wie ihr nun Christus Jesus, den Herrn, angenommen habt, so lebt nun auch in ihm: verwurzelt in ihm und aufgebaut auf diesem Fundament, gefestigt im Glauben, so wie ihr unterrichtet worden seid.","lehrtextReference":"Kolosser 2,6-7"},"2026-02-14":{"text":"Der das Leben seiner Getreuen behütet, wird sie retten aus der Hand der Frevler.","reference":"Psalm 97,10","translation":"Losung","lehrtext":"So hatte nun die Gemeinde Frieden in ganz Judäa und Galiläa und Samarien und baute sich auf und lebte in der Furcht des Herrn und mehrte sich unter dem Beistand des Heiligen Geistes.","lehrtextReference":"Apostelgeschichte 9,31"},"2026-02-15":{"text":"/Josefs Brüder baten ihn:/ Nun vergib doch diese Missetat uns, den Dienern des Gottes deines Vaters!","reference":"1. Mose 50,17","translation":"Losung","lehrtext":"Seid untereinander freundlich und herzlich und vergebt einer dem andern, wie auch Gott euch vergeben hat in Christus.","lehrtextReference":"Epheser 4,32"},"2026-02-16":{"text":"Siehe, ich will meinen Engel senden, der vor mir her den Weg bereiten soll.","reference":"Maleachi 3,1","translation":"Losung","lehrtext":"Der Menschensohn wird die Engel senden und wird seine Auserwählten versammeln von den vier Winden, vom Ende der Erde bis zum Ende des Himmels.","lehrtextReference":"Markus 13,27"},"2026-02-17":{"text":"Was verborgen ist, ist des HERRN, unseres Gottes; was aber offenbart ist, das gilt uns und unsern Kindern ewiglich.","reference":"5. Mose 29,28","translation":"Losung","lehrtext":"Sie sollen das Geheimnis Gottes erkennen: Christus. In ihm sind alle Schätze der Weisheit und Erkenntnis verborgen.","lehrtextReference":"Kolosser 2,2-3"},"2026-02-18":{"text":"HERR, lass mir deine Gnade widerfahren, deine Hilfe nach deinem Wort.","reference":"Psalm 119,41","translation":"Losung","lehrtext":"Es kam eine Furcht über sie alle, und sie redeten miteinander und sprachen: Was ist das für ein Wort? Jesus gebietet mit Vollmacht und Gewalt den unreinen Geistern, und sie fahren aus.","lehrtextReference":"Lukas 4,36"},"2026-02-19":{"text":"Lobet, ihr Völker, unsern Gott, lasst seinen Ruhm weit erschallen, der unsre Seelen am Leben erhält und lässt unsere Füße nicht gleiten.","reference":"Psalm 66,8-9","translation":"Losung","lehrtext":"Der Gott der Geduld und des Trostes gebe euch, dass ihr einträchtig gesinnt seid untereinander, wie es Christus Jesus entspricht, damit ihr einmütig mit einem Munde Gott lobt, den Vater unseres Herrn Jesus Christus.","lehrtextReference":"Römer 15,5-6"},"2026-02-20":{"text":"Du, HERR, wollest deine Barmherzigkeit nicht von mir wenden; lass deine Güte und Treue allewege mich behüten.","reference":"Psalm 40,12","translation":"Losung","lehrtext":"Gott gebe euch viel Barmherzigkeit und Frieden und Liebe!","lehrtextReference":"Judas 1,2"},"2026-02-21":{"text":"Gedenkt nicht an das Frühere und achtet nicht auf das Vorige! Denn siehe, ich will ein Neues schaffen, jetzt wächst es auf, erkennt ihr’s denn nicht?","reference":"Jesaja 43,18-19","translation":"Losung","lehrtext":"/Paulus schreibt:/ Ist jemand in Christus, so ist er eine neue Kreatur; das Alte ist vergangen, siehe, Neues ist geworden.","lehrtextReference":"2. Korinther 5,17"},"2026-02-22":{"text":"Die Elenden werden wieder Freude haben am HERRN, und die Ärmsten unter den Menschen werden fröhlich sein in dem Heiligen Israels.","reference":"Jesaja 29,19","translation":"Losung","lehrtext":"Ihr kennt die Gnade unseres Herrn Jesus Christus: Obwohl er reich ist, wurde er doch arm um euretwillen, auf dass ihr durch seine Armut reich würdet.","lehrtextReference":"2. Korinther 8,9"},"2026-02-23":{"text":"Ruft laut, rühmt und sprecht: HERR, hilf deinem Volk!","reference":"Jeremia 31,7","translation":"Losung","lehrtext":"Gepriesen sei der Herr, der Gott Israels! Denn er hat sich seines Volkes angenommen und ihm Erlösung verschafft.","lehrtextReference":"Lukas 1,68"},"2026-02-24":{"text":"Ich weiß, dass der HERR des Elenden Sache führen und den Armen Recht schaffen wird.","reference":"Psalm 140,13","translation":"Losung","lehrtext":"Wenn ein Bruder oder eine Schwester nackt ist und Mangel hat an täglicher Nahrung und jemand unter euch spricht zu ihnen: Geht hin in Frieden, wärmt euch und sättigt euch!, ihr gebt ihnen aber nicht, was der Leib nötig hat – was hilft ihnen das?","lehrtextReference":"Jakobus 2,15-16"},"2026-02-25":{"text":"Ich, der HERR, habe dich gerufen in Gerechtigkeit und halte dich bei der Hand.","reference":"Jesaja 42,6","translation":"Losung","lehrtext":"Und siehe, eine Stimme aus der Wolke sprach: Dies ist mein lieber Sohn, an dem ich Wohlgefallen habe; den sollt ihr hören!","lehrtextReference":"Matthäus 17,5"},"2026-02-26":{"text":"Der Gerechten Pfad glänzt wie das Licht am Morgen, das immer heller leuchtet bis zum vollen Tag.","reference":"Sprüche 4,18","translation":"Losung","lehrtext":"Wenn ihr auch leidet um der Gerechtigkeit willen, so seid ihr doch selig.","lehrtextReference":"1. Petrus 3,14"},"2026-02-27":{"text":"Ach, HERR, lass doch deine Ohren aufmerken, dass du das Gebet hörst, das ich jetzt vor dir bete Tag und Nacht für deine Knechte.","reference":"Nehemia 1,6","translation":"Losung","lehrtext":"Sollte Gott nicht Recht schaffen seinen Auserwählten, die zu ihm Tag und Nacht rufen, und sollte er bei ihnen lange warten? Ich sage euch: Er wird ihnen Recht schaffen in Kürze.","lehrtextReference":"Lukas 18,7-8"},"2026-02-28":{"text":"Wie kehrt ihr alles um! Als ob der Ton dem Töpfer gleich wäre, dass das Werk spräche von seinem Meister: Er hat mich nicht gemacht!, und ein Bildwerk spräche von seinem Bildner: Er versteht nichts!","reference":"Jesaja 29,16","translation":"Losung","lehrtext":"Wir sind sein Werk, geschaffen in Christus Jesus zu guten Werken, die Gott zuvor bereitet hat, dass wir darin wandeln sollen.","lehrtextReference":"Epheser 2,10"},"2026-03-01":{"text":"Achtet ernstlich darauf um eures Lebens willen, dass ihr den HERRN, euren Gott, lieb habt.","reference":"Josua 23,11","translation":"Losung","lehrtext":"Das ist die Liebe zu Gott, dass wir seine Gebote halten; und seine Gebote sind nicht schwer.","lehrtextReference":"1. Johannes 5,3"},"2026-03-02":{"text":"Es werden sich zum HERRN bekehren aller Welt Enden.","reference":"Psalm 22,28","translation":"Losung","lehrtext":"Viele werden kommen von Osten und von Westen und mit Abraham und Isaak und Jakob im Himmelreich zu Tisch sitzen.","lehrtextReference":"Matthäus 8,11"},"2026-03-03":{"text":"Die Israeliten schrien zu dem HERRN und sprachen: Wir haben an dir gesündigt, denn wir haben unsern Gott verlassen.","reference":"Richter 10,10","translation":"Losung","lehrtext":"/Johannes der Täufer sprach:/ Kehrt um! Denn nahe gekommen ist das Himmelreich.","lehrtextReference":"Matthäus 3,2"},"2026-03-04":{"text":"Habe deine Lust am HERRN; der wird dir geben, was dein Herz wünscht.","reference":"Psalm 37,4","translation":"Losung","lehrtext":"Wenn nun ihr, die ihr doch böse seid, dennoch euren Kindern gute Gaben zu geben wisst, wie viel mehr wird euer Vater im Himmel Gutes geben denen, die ihn bitten!","lehrtextReference":"Matthäus 7,11"},"2026-03-05":{"text":"Meine Hand hat die Erde gegründet, und meine Rechte hat den Himmel ausgespannt. Ich rufe, und alles steht da.","reference":"Jesaja 48,13","translation":"Losung","lehrtext":"Herr, unser Gott, du bist würdig, zu nehmen Preis und Ehre und Kraft; denn du hast alle Dinge geschaffen, und durch deinen Willen waren sie und wurden sie geschaffen.","lehrtextReference":"Offenbarung 4,11"},"2026-03-06":{"text":"Der Gerechte erkennt die Sache der Armen.","reference":"Sprüche 29,7","translation":"Losung","lehrtext":"Jesus sprach zu dem Oberen: Es fehlt dir noch eines. Verkaufe alles, was du hast, und gib’s den Armen, so wirst du einen Schatz im Himmel haben, und komm und folge mir nach!","lehrtextReference":"Lukas 18,22"},"2026-03-07":{"text":"Warum sollen die Heiden sagen: Wo ist denn ihr Gott? Unser Gott ist im Himmel; er kann schaffen, was er will.","reference":"Psalm 115,2-3","translation":"Losung","lehrtext":"Jesus spricht: Wer mich sieht, der sieht den Vater.","lehrtextReference":"Johannes 14,9"},"2026-03-08":{"text":"Herr, hab ich Gnade gefunden vor deinen Augen, so geh nicht an deinem Knecht vorüber.","reference":"1. Mose 18,3","translation":"Losung","lehrtext":"Jesus sprach zu ihm: Zachäus, steig eilend herunter; denn ich muss heute in deinem Haus einkehren.","lehrtextReference":"Lukas 19,5"},"2026-03-09":{"text":"Himmel und Erde sind dein, du hast gegründet den Erdkreis und was darinnen ist. Nord und Süd hast du geschaffen.","reference":"Psalm 89,12-13","translation":"Losung","lehrtext":"Gott hat aus einem Menschen das ganze Menschengeschlecht gemacht, damit sie auf dem ganzen Erdboden wohnen.","lehrtextReference":"Apostelgeschichte 17,26"},"2026-03-10":{"text":"Fürchte dich nicht, ich bin mit dir; weiche nicht, denn ich bin dein Gott.","reference":"Jesaja 41,10","translation":"Losung","lehrtext":"Hilf uns, deinen Dienern, deine Botschaft mutig und offen zu verkünden.","lehrtextReference":"Apostelgeschichte 4,29"},"2026-03-11":{"text":"Meine Seele verlangt nach deinem Heil; ich hoffe auf dein Wort.","reference":"Psalm 119,81","translation":"Losung","lehrtext":"Am Abend brachten sie viele Besessene zu ihm; und er trieb die Geister aus durch sein Wort und machte alle Kranken gesund.","lehrtextReference":"Matthäus 8,16"},"2026-03-12":{"text":"Durch seine Wunden sind wir geheilt.","reference":"Jesaja 53,5","translation":"Losung","lehrtext":"Gott hat Jesus wegen unserer Verfehlungen in den Tod gegeben. Und er hat ihn auferweckt, damit wir vor Gott gerecht sind.","lehrtextReference":"Römer 4,25"},"2026-03-13":{"text":"Der HERR festigt dem die Schritte, dessen Weg ihm gefällt. Kommt er zu Fall, so stürzt er doch nicht, denn der HERR stützt seine Hand.","reference":"Psalm 37,23-24","translation":"Losung","lehrtext":"Petrus schrie: Herr, rette mich! Jesus aber streckte sogleich die Hand aus und ergriff ihn und sprach zu ihm: Du Kleingläubiger, warum hast du gezweifelt?","lehrtextReference":"Matthäus 14,30-31"},"2026-03-14":{"text":"Ich bin der HERR, dein Gott, der ich dich aus Ägyptenland, aus der Knechtschaft, geführt habe.","reference":"2. Mose 20,2","translation":"Losung","lehrtext":"Zur Freiheit seid ihr berufen worden, liebe Brüder und Schwestern. Auf eins jedoch gebt acht: dass die Freiheit nicht zu einem Vorwand für die Selbstsucht werde, sondern dient einander in der Liebe!","lehrtextReference":"Galater 5,13"},"2026-03-15":{"text":"Bei Gott steht die Kraft zu helfen und fallen zu lassen.","reference":"2. Chronik 25,8","translation":"Losung","lehrtext":"Verkauft man nicht zwei Sperlinge für einen Groschen? Dennoch fällt keiner von ihnen auf die Erde ohne euren Vater. Darum fürchtet euch nicht; ihr seid kostbarer als viele Sperlinge.","lehrtextReference":"Matthäus 10,29.31"},"2026-03-16":{"text":"Gott, du hast mich von Jugend auf gelehrt, und noch jetzt verkündige ich deine Wunder.","reference":"Psalm 71,17","translation":"Losung","lehrtext":"/Paulus schreibt an Timotheus:/ Du kennst von Kind auf die heiligen Schriften, die dich unterweisen können zur Seligkeit durch den Glauben an Christus Jesus.","lehrtextReference":"2. Timotheus 3,15"},"2026-03-17":{"text":"Sehet, dass ich’s allein bin und ist kein Gott neben mir! Ich kann töten und lebendig machen, ich kann schlagen und kann heilen, und niemand kann aus meiner Hand reißen.","reference":"5. Mose 32,39","translation":"Losung","lehrtext":"/Jesus betete:/ Vater, du hast dem Sohn Macht gegeben über alle Menschen, auf dass er ihnen alles gebe, was du ihm gegeben hast: das ewige Leben.","lehrtextReference":"Johannes 17,1.2"},"2026-03-18":{"text":"Wende dich zu mir und sei mir gnädig; stärke deinen Knecht mit deiner Kraft!","reference":"Psalm 86,16","translation":"Losung","lehrtext":"Wahrlich, wahrlich, ich sage euch: Wenn ihr den Vater um etwas bitten werdet in meinem Namen, wird er’s euch geben.","lehrtextReference":"Johannes 16,23"},"2026-03-19":{"text":"Ich will die Übriggebliebenen meiner Herde sammeln aus allen Ländern und will sie wiederbringen zu ihren Weideplätzen, dass sie fruchtbar sein sollen und sich mehren.","reference":"Jeremia 23,3","translation":"Losung","lehrtext":"/Jesus spricht:/ Ich bin gekommen, damit sie das Leben haben und volle Genüge.","lehrtextReference":"Johannes 10,10"},"2026-03-20":{"text":"Sieh an meinen Jammer und mein Elend und vergib mir alle meine Sünden!","reference":"Psalm 25,18","translation":"Losung","lehrtext":"Ich elender Mensch! Wer wird mich erlösen von diesem Leib des Todes? Dank sei Gott durch Jesus Christus, unsern Herrn!","lehrtextReference":"Römer 7,24-25"},"2026-03-21":{"text":"Wenn du gegessen hast und satt bist, sollst du den HERRN, deinen Gott, loben.","reference":"5. Mose 8,10","translation":"Losung","lehrtext":"Gott sei Dank für seine unaussprechliche Gabe!","lehrtextReference":"2. Korinther 9,15"},"2026-03-22":{"text":"Du sollst nicht falsch Zeugnis reden wider deinen Nächsten.","reference":"2. Mose 20,16","translation":"Losung","lehrtext":"Ihr wisst, dass keine Lüge aus der Wahrheit kommt.","lehrtextReference":"1. Johannes 2,21"},"2026-03-23":{"text":"Ich, ich bin der HERR, und außer mir ist kein Heiland.","reference":"Jesaja 43,11","translation":"Losung","lehrtext":"/Jesus spricht:/ Ich und der Vater sind eins.","lehrtextReference":"Johannes 10,30"},"2026-03-24":{"text":"Der HERR wird seinen Engel vor dir her senden.","reference":"1. Mose 24,7","translation":"Losung","lehrtext":"Jesus sprach: Vater, willst du, so nimm diesen Kelch von mir; doch nicht mein, sondern dein Wille geschehe! Es erschien ihm aber ein Engel vom Himmel und stärkte ihn.","lehrtextReference":"Lukas 22,42-43"},"2026-03-25":{"text":"HERR, steh auf, dass nicht Menschen die Oberhand gewinnen.","reference":"Psalm 9,20","translation":"Losung","lehrtext":"Jesus sprach zu seinen Jüngern: Der Menschensohn wird überantwortet werden in die Hände der Menschen, und sie werden ihn töten; und wenn er getötet ist, so wird er nach drei Tagen auferstehen.","lehrtextReference":"Markus 9,31"},"2026-03-26":{"text":"Ich will den HERRN loben allezeit; sein Lob soll immerdar in meinem Munde sein.","reference":"Psalm 34,2","translation":"Losung","lehrtext":"Gott hat uns dazu vorherbestimmt, seine Kinder zu sein durch Jesus Christus nach dem Wohlgefallen seines Willens, zum Lob seiner herrlichen Gnade.","lehrtextReference":"Epheser 1,5-6"},"2026-03-27":{"text":"Gerechtigkeit führt zum Leben; aber dem Bösen nachjagen führt zum Tode.","reference":"Sprüche 11,19","translation":"Losung","lehrtext":"Wer auf den Boden seiner selbstsüchtigen Natur sät, wird von seiner Selbstsucht das Verderben ernten. Aber wer auf den Boden von Gottes Geist sät, wird von diesem Geist das ewige Leben ernten.","lehrtextReference":"Galater 6,8"},"2026-03-28":{"text":"Lass uns leben, so wollen wir deinen Namen anrufen.","reference":"Psalm 80,19","translation":"Losung","lehrtext":"Einer aber unter den zehn aussätzigen Männern, als er sah, dass er gesund geworden war, kehrte er um und pries Gott mit lauter Stimme.","lehrtextReference":"Lukas 17,15"},"2026-03-29":{"text":"Mose sprach zu dem HERRN: Wenn nicht dein Angesicht vorangeht, so führe uns nicht von hier hinauf.","reference":"2. Mose 33,15","translation":"Losung","lehrtext":"Sie nahmen Palmzweige und gingen hinaus Jesus entgegen und schrien: Hosianna! Gelobt sei, der da kommt im Namen des Herrn, der König von Israel!","lehrtextReference":"Johannes 12,13"},"2026-03-30":{"text":"Ihr sollt nichts dazutun zu dem, was ich euch gebiete, und sollt auch nichts davontun, auf dass ihr bewahrt die Gebote des HERRN, eures Gottes.","reference":"5. Mose 4,2","translation":"Losung","lehrtext":"/Paulus schreibt:/ Ich werde es nicht wagen, etwas vorzubringen, das nicht Christus durch mich gewirkt hat. Er hat es durch mein Wort und meine Tat bewirkt, dass die Völker nun Gott gehorsam sind.","lehrtextReference":"Römer 15,18"},"2026-03-31":{"text":"Der HERR, unser Gott, ist gerecht in allen seinen Werken, die er tut.","reference":"Daniel 9,14","translation":"Losung","lehrtext":"Musste nicht der Christus dies erleiden und in seine Herrlichkeit eingehen?","lehrtextReference":"Lukas 24,26"},"2026-04-01":{"text":"Ich will dir danken in großer Gemeinde; unter vielem Volk will ich dich rühmen.","reference":"Psalm 35,18","translation":"Losung","lehrtext":"Alle Zungen sollen bekennen, dass Jesus Christus der Herr ist, zur Ehre Gottes, des Vaters.","lehrtextReference":"Philipper 2,11"},"2026-04-02":{"text":"Wohl dem, dessen Hilfe der Gott Jakobs ist, der seine Hoffnung setzt auf den HERRN.","reference":"Psalm 146,5","translation":"Losung","lehrtext":"Jesus nahm den Kelch und dankte, gab ihnen den und sprach: Trinket alle daraus; das ist mein Blut des Bundes, das vergossen wird für viele zur Vergebung der Sünden.","lehrtextReference":"Matthäus 26,27-28"},"2026-04-03":{"text":"Lobt den HERRN, alle Völker! Rühmt ihn, ihr Nationen alle!","reference":"Psalm 117,1","translation":"Losung","lehrtext":"Die um den Thron sprachen mit großer Stimme: Das Lamm, das geschlachtet ist, ist würdig, zu nehmen Kraft und Reichtum und Weisheit und Stärke und Ehre und Preis und Lob.","lehrtextReference":"Offenbarung 5,12"},"2026-04-04":{"text":"Wie lieblich sind deine Wohnungen, HERR Zebaoth!","reference":"Psalm 84,2","translation":"Losung","lehrtext":"In meines Vaters Hause sind viele Wohnungen. Wenn’s nicht so wäre, hätte ich dann zu euch gesagt: Ich gehe hin, euch die Stätte zu bereiten?","lehrtextReference":"Johannes 14,2"},"2026-04-05":{"text":"Du bereitest vor mir einen Tisch im Angesicht meiner Feinde. Du salbest mein Haupt mit Öl und schenkest mir voll ein.","reference":"Psalm 23,5","translation":"Losung","lehrtext":"Der letzte Feind, der vernichtet wird, ist der Tod.","lehrtextReference":"1. Korinther 15,26"},"2026-04-06":{"text":"Er behütete sein Volk wie seinen Augapfel.","reference":"5. Mose 32,10","translation":"Losung","lehrtext":"Denn ich bin gewiss, dass weder Tod noch Leben, weder Engel noch Mächte noch Gewalten, weder Gegenwärtiges noch Zukünftiges, weder Hohes noch Tiefes noch irgendeine andere Kreatur uns scheiden kann von der Liebe Gottes, die in Christus Jesus ist, unserm Herrn.","lehrtextReference":"Römer 8,38-39"},"2026-04-07":{"text":"Der HERR schafft Recht den Waisen und Witwen und hat Fremdlinge lieb, dass er ihnen Speise und Kleider gibt. Darum sollt ihr auch die Fremdlinge lieben.","reference":"5. Mose 10,18-19","translation":"Losung","lehrtext":"Da wird dann der König sagen zu denen zu seiner Rechten: Kommt her, ihr Gesegneten meines Vaters, ererbt das Reich, das euch bereitet ist von Anbeginn der Welt! Ich bin nackt gewesen und ihr habt mich gekleidet.","lehrtextReference":"Matthäus 25,34.36"},"2026-04-08":{"text":"Bedrückt nicht die Witwen, Waisen, Fremdlinge und Armen!","reference":"Sacharja 7,10","translation":"Losung","lehrtext":"Da wird dann der König sagen zu denen zu seiner Rechten: Kommt her, ihr Gesegneten meines Vaters, ererbt das Reich, das euch bereitet ist von Anbeginn der Welt! Ich bin ein Fremder gewesen und ihr habt mich aufgenommen.","lehrtextReference":"Matthäus 25,34.35"},"2026-04-09":{"text":"Sei nicht schnell mit deinem Munde und lass dein Herz nicht eilen, etwas zu reden vor Gott; denn Gott ist im Himmel und du auf Erden; darum lass deiner Worte wenig sein.","reference":"Prediger 5,1","translation":"Losung","lehrtext":"/Jesus spricht:/ Euer Vater weiß, was ihr braucht, noch ehe ihr ihn bittet.","lehrtextReference":"Matthäus 6,8"},"2026-04-10":{"text":"/Der HERR sprach zu Jakob:/ Siehe, ich bin mit dir und will dich behüten, wo du hinziehst, und will dich wieder herbringen in dies Land.","reference":"1. Mose 28,15","translation":"Losung","lehrtext":"Jesus sprach zu den Jüngern: Als ich euch ausgesandt habe ohne Geldbeutel, ohne Tasche und ohne Schuhe, habt ihr je Mangel gehabt? Sie sprachen: Nein, keinen.","lehrtextReference":"Lukas 22,35"},"2026-04-11":{"text":"Meine Schuld ist mir über den Kopf gewachsen; sie wiegt zu schwer, ich kann sie nicht mehr tragen.","reference":"Psalm 38,5","translation":"Losung","lehrtext":"Der Übeltäter sprach: Jesus, gedenke an mich, wenn du in dein Reich kommst! Und Jesus sprach zu ihm: Wahrlich, ich sage dir: Heute wirst du mit mir im Paradies sein.","lehrtextReference":"Lukas 23,42-43"},"2026-04-12":{"text":"Sei nun wieder zufrieden, meine Seele; denn der HERR tut dir Gutes.","reference":"Psalm 116,7","translation":"Losung","lehrtext":"Jesus kam, obwohl die Türen verschlossen waren, und er trat in ihre Mitte und sprach: Friede sei mit euch!","lehrtextReference":"Johannes 20,26"},"2026-04-13":{"text":"Meine Zeit steht in deinen Händen.","reference":"Psalm 31,16","translation":"Losung","lehrtext":"So seht nun sorgfältig darauf, wie ihr euer Leben führt, nicht als Unweise, sondern als Weise.","lehrtextReference":"Epheser 5,15"},"2026-04-14":{"text":"David sprach zum HERRN: Ich habe schwer gesündigt, dass ich das getan habe. Und nun, HERR, nimm weg die Schuld deines Knechts.","reference":"2. Samuel 24,10","translation":"Losung","lehrtext":"Wenn wir unsre Sünden bekennen, so ist er treu und gerecht, dass er uns die Sünden vergibt und reinigt uns von aller Ungerechtigkeit.","lehrtextReference":"1. Johannes 1,9"},"2026-04-15":{"text":"Vor dem HERRN her kam ein großer und gewaltiger Sturmwind, der Berge zerriss und Felsen zerbrach, in dem Sturmwind aber war der HERR nicht. Und nach dem Sturmwind kam ein Erdbeben, in dem Erdbeben aber war der HERR nicht. Und nach dem Erdbeben kam ein Feuer, in dem Feuer aber war der HERR nicht. Nach dem Feuer aber kam das Flüstern eines sanften Windhauchs.","reference":"1. Könige 19,11-12","translation":"Losung","lehrtext":"Kein Mensch hat Gott jemals gesehen. Nur der Eine, der selbst Gott ist und mit dem Vater in engster Gemeinschaft steht, hat uns gesagt und gezeigt, wer Gott ist.","lehrtextReference":"Johannes 1,18"},"2026-04-16":{"text":"Der HERR sprach zu Jona: Meinst du, dass du mit Recht zürnst?","reference":"Jona 4,4","translation":"Losung","lehrtext":"Seid barmherzig, wie auch euer Vater barmherzig ist.","lehrtextReference":"Lukas 6,36"},"2026-04-17":{"text":"Gott, du holst mich wieder herauf aus den Tiefen der Erde. Du machst mich sehr groß und tröstest mich wieder.","reference":"Psalm 71,20-21","translation":"Losung","lehrtext":"Jesus sprach: Jüngling, ich sage dir, steh auf! Und der Tote richtete sich auf und fing an zu reden, und Jesus gab ihn seiner Mutter.","lehrtextReference":"Lukas 7,14-15"},"2026-04-18":{"text":"Der HERR, dein Gott, ist ein verzehrendes Feuer und ein eifernder Gott.","reference":"5. Mose 4,24","translation":"Losung","lehrtext":"Darum, weil wir ein Reich empfangen, das nicht erschüttert wird, lasst uns dankbar sein und so Gott dienen mit Scheu und Furcht, wie es ihm gefällt.","lehrtextReference":"Hebräer 12,28"},"2026-04-19":{"text":"Ich will das Verlorene wieder suchen und das Verirrte zurückbringen und das Verwundete verbinden und das Schwache stärken.","reference":"Hesekiel 34,16","translation":"Losung","lehrtext":"Ihr irrtet umher wie Schafe, doch jetzt seid ihr zurückgekehrt zum Hirten, zum Beschützer eurer Seelen.","lehrtextReference":"1. Petrus 2,25"},"2026-04-20":{"text":"Haltet mich nicht auf, denn der HERR hat Gnade zu meiner Reise gegeben.","reference":"1. Mose 24,56","translation":"Losung","lehrtext":"/Jesus sprach:/ Es ist gut für euch, dass ich weggehe. Denn wenn ich nicht weggehe, kommt der Tröster nicht zu euch. Wenn ich aber gehe, werde ich ihn zu euch senden.","lehrtextReference":"Johannes 16,7"},"2026-04-21":{"text":"Gott, du bleibst, wie du bist, und deine Jahre nehmen kein Ende.","reference":"Psalm 102,28","translation":"Losung","lehrtext":"Dem alleinigen Gott, unserm Heiland durch unsern Herrn Jesus Christus, sei Ehre und Majestät und Gewalt und Macht vor aller Zeit, jetzt und in alle Ewigkeit! Amen.","lehrtextReference":"Judas 1,25"},"2026-04-22":{"text":"Du erkennst ja in deinem Herzen, dass der HERR, dein Gott, dich erzogen hat, wie ein Mann seinen Sohn erzieht.","reference":"5. Mose 8,5","translation":"Losung","lehrtext":"Alle Schrift, von Gott eingegeben, ist nütze zur Lehre, zur Zurechtweisung, zur Besserung, zur Erziehung in der Gerechtigkeit.","lehrtextReference":"2. Timotheus 3,16"},"2026-04-23":{"text":"Der Himmel ist der Himmel des HERRN; aber die Erde hat er den Menschenkindern gegeben.","reference":"Psalm 115,16","translation":"Losung","lehrtext":"Deshalb beuge ich meine Knie vor dem Vater, von dem jedes Geschlecht im Himmel und auf Erden seinen Namen hat.","lehrtextReference":"Epheser 3,14-15"},"2026-04-24":{"text":"Pflüget ein Neues und säet nicht unter die Dornen!","reference":"Jeremia 4,3","translation":"Losung","lehrtext":"Jesus sprach: Wer die Hand an den Pflug legt und sieht zurück, der ist nicht geschickt für das Reich Gottes.","lehrtextReference":"Lukas 9,62"},"2026-04-25":{"text":"Das Erdreich erschrickt und wird still, wenn Gott sich aufmacht zu richten, dass er helfe allen Elenden auf Erden.","reference":"Psalm 76,9-10","translation":"Losung","lehrtext":"Das Evangelium muss zuvor gepredigt werden unter allen Völkern.","lehrtextReference":"Markus 13,10"},"2026-04-26":{"text":"Gott hat den Menschen aufrichtig gemacht; aber sie suchen viele Künste.","reference":"Prediger 7,29","translation":"Losung","lehrtext":"Es ist erschienen die heilsame Gnade Gottes allen Menschen und erzieht uns, dass wir absagen dem gottlosen Wesen und den weltlichen Begierden und besonnen, gerecht und fromm in dieser Welt leben.","lehrtextReference":"Titus 2,11-12"},"2026-04-27":{"text":"Zeige deinen Knechten deine Werke und deine Herrlichkeit ihren Kindern.","reference":"Psalm 90,16","translation":"Losung","lehrtext":"Seht die Lilien, wie sie wachsen: Sie arbeiten nicht, auch spinnen sie nicht. Ich sage euch aber, dass auch Salomo in aller seiner Herrlichkeit nicht gekleidet gewesen ist wie eine von ihnen.","lehrtextReference":"Lukas 12,27"},"2026-04-28":{"text":"Ach, Herr, du großer und schrecklicher Gott, der du Bund und Gnade bewahrst denen, die dich lieben und deine Gebote halten! Wir haben gesündigt und Unrecht getan.","reference":"Daniel 9,4-5","translation":"Losung","lehrtext":"/Jesus spricht:/ Wer zu mir kommt, den werde ich nicht hinausstoßen.","lehrtextReference":"Johannes 6,37"},"2026-04-29":{"text":"Tu deinen Mund auf für die Stummen und für die Sache aller, die verlassen sind.","reference":"Sprüche 31,8","translation":"Losung","lehrtext":"Da sie ihn nicht zu Jesus bringen konnten wegen der Menge, deckten sie das Dach auf, wo er war, gruben es auf und ließen das Bett herunter, auf dem der Gelähmte lag.","lehrtextReference":"Markus 2,4"},"2026-04-30":{"text":"Tausend Jahre sind vor dir wie der Tag, der gestern vergangen ist, und wie eine Nachtwache.","reference":"Psalm 90,4","translation":"Losung","lehrtext":"Der Herr verzögert nicht die Verheißung, wie es einige für eine Verzögerung halten; sondern er hat Geduld mit euch und will nicht, dass jemand verloren werde, sondern dass jedermann zur Buße finde.","lehrtextReference":"2. Petrus 3,9"},"2026-05-01":{"text":"Mich sollst du fürchten und dich zurechtweisen lassen.","reference":"Zefanja 3,7","translation":"Losung","lehrtext":"Wer sollte dich, Herr, nicht fürchten und deinen Namen nicht preisen? Denn du allein bist heilig!","lehrtextReference":"Offenbarung 15,4"},"2026-05-02":{"text":"Lass meinen Gang in deinem Wort fest sein und lass kein Unrecht über mich herrschen.","reference":"Psalm 119,133","translation":"Losung","lehrtext":"Wer von sich sagt, dass er mit Gott verbunden ist, soll auch so leben, wie Jesus gelebt hat.","lehrtextReference":"1. Johannes 2,6"},"2026-05-03":{"text":"Gideon sprach zu dem HERRN: Hab ich Gnade vor dir gefunden, so mach mir doch ein Zeichen, dass du es bist, der mit mir redet.","reference":"Richter 6,17","translation":"Losung","lehrtext":"Nikodemus sprach zu Jesus: Rabbi, wir wissen, dass du ein Lehrer bist, von Gott gekommen; denn niemand kann die Zeichen tun, die du tust, es sei denn Gott mit ihm.","lehrtextReference":"Johannes 3,2"},"2026-05-04":{"text":"Gelobt sei der Herr täglich. Gott legt uns eine Last auf, aber er hilft uns auch.","reference":"Psalm 68,20","translation":"Losung","lehrtext":"/Jesus spricht:/ Kommt her zu mir, alle, die ihr mühselig und beladen seid; ich will euch erquicken.","lehrtextReference":"Matthäus 11,28"},"2026-05-05":{"text":"Der HERR hebe sein Angesicht über dich und gebe dir Frieden.","reference":"4. Mose 6,26","translation":"Losung","lehrtext":"Der Gott, der gesagt hat: Aus der Finsternis soll Licht aufstrahlen, er ist es, der es hat aufstrahlen lassen in unseren Herzen, so dass die Erkenntnis aufleuchtet, die Erkenntnis der Herrlichkeit Gottes auf dem Angesicht Jesu Christi.","lehrtextReference":"2. Korinther 4,6"},"2026-05-06":{"text":"Sie werden weinend kommen, aber ich will sie trösten und leiten. Ich will sie zu Wasserbächen führen auf ebenem Wege, auf dem sie nicht straucheln; denn ich bin Israels Vater.","reference":"Jeremia 31,9","translation":"Losung","lehrtext":"Christus hat in den Tagen seines irdischen Lebens Bitten und Flehen mit lautem Schreien und mit Tränen vor den gebracht, der ihn aus dem Tod erretten konnte; und er ist erhört worden, weil er Gott in Ehren hielt.","lehrtextReference":"Hebräer 5,7"},"2026-05-07":{"text":"HERR, frühe wollest du meine Stimme hören, frühe will ich mich zu dir wenden und aufmerken.","reference":"Psalm 5,4","translation":"Losung","lehrtext":"Am Morgen, noch vor Tage, stand Jesus auf und ging hinaus. Und er ging an eine einsame Stätte und betete dort.","lehrtextReference":"Markus 1,35"},"2026-05-08":{"text":"Der HERR, unser Gott, verlasse uns nicht und ziehe die Hand nicht ab von uns.","reference":"1. Könige 8,57","translation":"Losung","lehrtext":"Jesus sprach: Mir ist gegeben alle Gewalt im Himmel und auf Erden.","lehrtextReference":"Matthäus 28,18"},"2026-05-09":{"text":"Ich will euch retten, dass ihr ein Segen sein sollt.","reference":"Sacharja 8,13","translation":"Losung","lehrtext":"Gott tröstet uns in aller unserer Bedrängnis, damit wir auch trösten können, die in allerlei Bedrängnis sind, mit dem Trost, mit dem wir selber getröstet werden von Gott.","lehrtextReference":"2. Korinther 1,4"},"2026-05-10":{"text":"Unser Gott, den wir verehren, kann uns erretten aus dem glühenden Feuerofen. Und wenn er’s nicht tut, so sollst du dennoch wissen, dass wir deinen Gott nicht ehren und das goldene Bild nicht anbeten werden.","reference":"Daniel 3,17.18","translation":"Losung","lehrtext":"Das sagt der Heilige, der Wahrhaftige: Ich kenne deine Werke. Siehe, ich habe vor dir eine Tür aufgetan, die niemand zuschließen kann; du hast eine kleine Kraft und hast mein Wort bewahrt und hast meinen Namen nicht verleugnet.","lehrtextReference":"Offenbarung 3,7.8"},"2026-05-11":{"text":"Es ist niemand heilig wie der HERR, außer dir ist keiner.","reference":"1. Samuel 2,2","translation":"Losung","lehrtext":"Heilig, heilig, heilig ist Gott der Herr, der Allmächtige, der da war und der da ist und der da kommt.","lehrtextReference":"Offenbarung 4,8"},"2026-05-12":{"text":"Der HERR wendet sich zum Gebet der Verlassenen und verschmäht ihr Gebet nicht.","reference":"Psalm 102,18","translation":"Losung","lehrtext":"Des Gerechten Gebet vermag viel, wenn es ernstlich ist.","lehrtextReference":"Jakobus 5,16"},"2026-05-13":{"text":"In Gottes Hand ist die Seele von allem, was lebt.","reference":"Hiob 12,10","translation":"Losung","lehrtext":"Jesus rief laut: Vater, ich befehle meinen Geist in deine Hände! Und als er das gesagt hatte, verschied er.","lehrtextReference":"Lukas 23,46"},"2026-05-14":{"text":"Dein Herz eifre nicht gegen die Sünder, sondern jederzeit nach der Furcht des HERRN.","reference":"Sprüche 23,17","translation":"Losung","lehrtext":"Jesus sprach zu den Jüngern: So steht’s geschrieben, dass der Christus leiden wird und auferstehen von den Toten am dritten Tage; und dass gepredigt wird in seinem Namen Buße zur Vergebung der Sünden unter allen Völkern. Von Jerusalem an seid ihr dafür Zeugen.","lehrtextReference":"Lukas 24,46-48"},"2026-05-15":{"text":"Kommt, wir wollen uns dem HERRN zuwenden zu einem ewigen Bunde, der nimmermehr vergessen werden soll!","reference":"Jeremia 50,5","translation":"Losung","lehrtext":"Bemüht euch deshalb nach Kräften, dass zu eurem Glauben das richtige Verhalten kommt. Zum richtigen Verhalten soll die Erkenntnis kommen, zur Erkenntnis die Selbstbeherrschung, zur Selbstbeherrschung die Standhaftigkeit, zur Standhaftigkeit die Ausübung des Glaubens, zur Ausübung des Glaubens die geschwisterliche Liebe und zur geschwisterlichen Liebe die Liebe überhaupt.","lehrtextReference":"2. Petrus 1,5-7"},"2026-05-16":{"text":"Gott ist weise und mächtig; wer stellte sich ihm entgegen und blieb unversehrt?","reference":"Hiob 9,4","translation":"Losung","lehrtext":"Gott widersteht den Hochmütigen, aber den Demütigen gibt er Gnade.","lehrtextReference":"1. Petrus 5,5"},"2026-05-17":{"text":"HERR, du hast mich heraufgeholt aus dem Totenreich, zum Leben mich zurückgerufen von denen, die hinab zur Grube fuhren.","reference":"Psalm 30,4","translation":"Losung","lehrtext":"Jesus rief mit lauter Stimme: Lazarus, komm heraus! Und der Verstorbene kam heraus, gebunden mit Grabtüchern an Füßen und Händen, und sein Gesicht war verhüllt mit einem Schweißtuch.","lehrtextReference":"Johannes 11,43-44"},"2026-05-18":{"text":"Nicht uns, HERR, nicht uns, sondern deinem Namen gib Ehre um deiner Gnade und Treue willen!","reference":"Psalm 115,1","translation":"Losung","lehrtext":"/Jesus spricht:/ Wer von sich aus redet, sucht die eigene Ehre; wer aber die Ehre dessen sucht, der ihn gesandt hat, der ist glaubwürdig, und keine Ungerechtigkeit ist in ihm.","lehrtextReference":"Johannes 7,18"},"2026-05-19":{"text":"HERR, du bist doch unser Vater! Wir sind Ton, du bist unser Töpfer, und wir alle sind deiner Hände Werk.","reference":"Jesaja 64,7","translation":"Losung","lehrtext":"Ja, lieber Mensch, wer bist du denn, dass du mit Gott rechten willst? Spricht etwa ein Werk zu seinem Meister: Warum hast du mich so gemacht?","lehrtextReference":"Römer 9,20"},"2026-05-20":{"text":"Ich will singen von der Gnade des HERRN ewiglich und seine Treue verkünden mit meinem Munde für und für.","reference":"Psalm 89,2","translation":"Losung","lehrtext":"Die Jünger zogen aus und predigten an allen Orten. Und der Herr wirkte mit ihnen und bekräftigte das Wort durch die mitfolgenden Zeichen.","lehrtextReference":"Markus 16,20"},"2026-05-21":{"text":"Lobet Gott für seine Taten, lobet ihn in seiner großen Herrlichkeit!","reference":"Psalm 150,2","translation":"Losung","lehrtext":"Mit Psalmen, Lobgesängen und geistlichen Liedern singt Gott dankbar in euren Herzen.","lehrtextReference":"Kolosser 3,16"},"2026-05-22":{"text":"Der HERR ist dein Ruhm, und er ist dein Gott.","reference":"5. Mose 10,21","translation":"Losung","lehrtext":"Er selbst, der Vater, hat euch lieb.","lehrtextReference":"Johannes 16,27"},"2026-05-23":{"text":"Gott tut große Dinge, die wir nicht begreifen.","reference":"Hiob 37,5","translation":"Losung","lehrtext":"Er lässt seine Sonne aufgehen über Böse und Gute und lässt regnen über Gerechte und Ungerechte.","lehrtextReference":"Matthäus 5,45"},"2026-05-24":{"text":"Machet die Tore weit und die Türen in der Welt hoch, dass der König der Ehre einziehe!","reference":"Psalm 24,7","translation":"Losung","lehrtext":"Es geschah plötzlich ein Brausen vom Himmel wie von einem gewaltigen Sturm und erfüllte das ganze Haus, in dem sie saßen. Und sie wurden alle erfüllt von dem Heiligen Geist.","lehrtextReference":"Apostelgeschichte 2,2.4"},"2026-05-25":{"text":"Mächtig waltet über uns seine Güte, und die Treue des HERRN währt in Ewigkeit. Halleluja.","reference":"Psalm 117,2","translation":"Losung","lehrtext":"Es wohnten in Jerusalem Juden, die waren gottesfürchtige Männer aus allen Völkern unter dem Himmel. Sie entsetzten sich aber, verwunderten sich und sprachen: Wir hören sie in unsern Sprachen die großen Taten Gottes verkünden.","lehrtextReference":"Apostelgeschichte 2,5.7.11"},"2026-05-26":{"text":"Die ihr den HERRN liebet, hasset das Arge!","reference":"Psalm 97,10","translation":"Losung","lehrtext":"Weist die zurecht, die sich an keine Ordnung halten, ermutigt die Verzagten, steht den Schwachen bei, habt Geduld mit allen!","lehrtextReference":"1. Thessalonicher 5,14"},"2026-05-27":{"text":"HERR, wer ist dir gleich unter den Göttern? Wer ist dir gleich, der so herrlich und heilig ist, schrecklich, löblich und wundertätig?","reference":"2. Mose 15,11","translation":"Losung","lehrtext":"Obwohl es solche gibt, die Götter genannt werden, es sei im Himmel oder auf Erden, wie es ja viele Götter und viele Herren gibt, so haben wir doch nur #einen# Gott, den Vater, von dem alle Dinge sind und wir zu ihm, und #einen# Herrn, Jesus Christus, durch den alle Dinge sind und wir durch ihn.","lehrtextReference":"1. Korinther 8,5-6"},"2026-05-28":{"text":"Ich weiß, dass mein Erlöser lebt.","reference":"Hiob 19,25","translation":"Losung","lehrtext":"Christus ist auferweckt von den Toten als Erstling unter denen, die entschlafen sind.","lehrtextReference":"1. Korinther 15,20"},"2026-05-29":{"text":"Ich habe erkannt, HERR, dass der Mensch nicht über seinen Weg bestimmt.","reference":"Jeremia 10,23","translation":"Losung","lehrtext":"/Der reiche Mensch sprach:/ Liebe Seele, du hast einen großen Vorrat für viele Jahre; habe nun Ruhe, iss, trink und habe guten Mut! Aber Gott sprach zu ihm: Du Narr! Diese Nacht wird man deine Seele von dir fordern. Und wem wird dann gehören, was du bereitet hast?","lehrtextReference":"Lukas 12,19-20"},"2026-05-30":{"text":"Der HERR, der gütig ist, wolle gnädig sein allen, die ihr Herz darauf richten, Gott zu suchen.","reference":"2. Chronik 30,18-19","translation":"Losung","lehrtext":"/Jesus erzählt im Gleichnis:/ Der Sohn machte sich auf und kam zu seinem Vater. Als er aber noch weit entfernt war, sah ihn sein Vater und es jammerte ihn, und er lief und fiel ihm um den Hals und küsste ihn.","lehrtextReference":"Lukas 15,20"},"2026-05-31":{"text":"Wie schwer sind für mich, Gott, deine Gedanken! Wie ist ihre Summe so groß!","reference":"Psalm 139,17","translation":"Losung","lehrtext":"O welch eine Tiefe des Reichtums, beides, der Weisheit und der Erkenntnis Gottes! Wie unbegreiflich sind seine Gerichte und unerforschlich seine Wege!","lehrtextReference":"Römer 11,33"},"2026-06-01":{"text":"Ich will rühmen Gottes Wort; ich will rühmen des HERRN Wort.","reference":"Psalm 56,11","translation":"Losung","lehrtext":"Das Wort ward Fleisch und wohnte unter uns, und wir sahen seine Herrlichkeit, eine Herrlichkeit als des eingeborenen Sohnes vom Vater, voller Gnade und Wahrheit.","lehrtextReference":"Johannes 1,14"},"2026-06-02":{"text":"/Boas sprach zu Rut:/ Du bist gekommen zu dem HERRN, dass du unter seinen Flügeln Zuflucht hättest.","reference":"Rut 2,12","translation":"Losung","lehrtext":"Wer zu Gott kommen will, der muss glauben, dass er ist und dass er denen, die ihn suchen, ihren Lohn gibt.","lehrtextReference":"Hebräer 11,6"},"2026-06-03":{"text":"Der HERR macht die Blinden sehend.","reference":"Psalm 146,8","translation":"Losung","lehrtext":"Jesus antwortete und sprach zu ihnen: Geht und verkündet Johannes, was ihr gesehen und gehört habt: Blinde sehen, Lahme gehen, Aussätzige werden rein und Taube hören, Tote stehen auf, Armen wird das Evangelium gepredigt.","lehrtextReference":"Lukas 7,22"},"2026-06-04":{"text":"Der HERR, dein Gott, wird dir Glück geben zu allen Werken deiner Hände.","reference":"5. Mose 30,9","translation":"Losung","lehrtext":"Niemand gehe zu weit und übervorteile seinen Bruder im Handel. Denn der Herr straft dies alles.","lehrtextReference":"1. Thessalonicher 4,6"},"2026-06-05":{"text":"Harre des HERRN! Sei getrost und unverzagt und harre des HERRN!","reference":"Psalm 27,14","translation":"Losung","lehrtext":"Marta sprach zu Jesus: Herr, wärst du hier gewesen, mein Bruder wäre nicht gestorben. Aber auch jetzt weiß ich: Was du bittest von Gott, das wird dir Gott geben.","lehrtextReference":"Johannes 11,21-22"},"2026-06-06":{"text":"/David betete:/ So bekräftige nun, HERR, Gott, das Wort in Ewigkeit, das du über deinen Knecht und über sein Haus geredet hast, und tu, wie du geredet hast!","reference":"2. Samuel 7,25","translation":"Losung","lehrtext":"Aus Davids Geschlecht hat Gott, wie er verheißen hat, Jesus kommen lassen als Heiland für das Volk Israel.","lehrtextReference":"Apostelgeschichte 13,23"},"2026-06-07":{"text":"HERR, wenn ich mitten in der Angst wandle, so erquickst du mich.","reference":"Psalm 138,7","translation":"Losung","lehrtext":"/Jesus Christus spricht:/ In der Welt habt ihr Angst; aber seid getrost, ich habe die Welt überwunden.","lehrtextReference":"Johannes 16,33"},"2026-06-08":{"text":"Ich dachte, ich arbeitete vergeblich und verzehrte meine Kraft umsonst und unnütz. Doch mein Recht ist bei dem HERRN und mein Lohn bei meinem Gott.","reference":"Jesaja 49,4","translation":"Losung","lehrtext":"Simon sprach: Meister, wir haben die ganze Nacht gearbeitet und nichts gefangen; aber auf dein Wort hin will ich die Netze auswerfen.","lehrtextReference":"Lukas 5,5"},"2026-06-09":{"text":"Jakob zog seinen Weg. Und es begegneten ihm die Engel Gottes.","reference":"1. Mose 32,2","translation":"Losung","lehrtext":"/Paulus sprach:/ Diese Nacht trat zu mir der Engel des Gottes, dem ich gehöre und dem ich diene, und sprach: Fürchte dich nicht, Paulus, du musst vor den Kaiser gestellt werden; und siehe, Gott hat dir geschenkt alle, die mit dir fahren.","lehrtextReference":"Apostelgeschichte 27,23-24"},"2026-06-10":{"text":"Wohlan, alle, die ihr durstig seid, kommt her zum Wasser!","reference":"Jesaja 55,1","translation":"Losung","lehrtext":"Jesus sprach zu ihnen: Wer an mich glaubt, den wird nimmermehr dürsten.","lehrtextReference":"Johannes 6,35"},"2026-06-11":{"text":"Habe ich dir nicht geboten: Sei getrost und unverzagt?","reference":"Josua 1,9","translation":"Losung","lehrtext":"/Paulus schreibt:/ Wir dachten bei uns selbst, zum Tode verurteilt zu sein. Das geschah aber, damit wir unser Vertrauen nicht auf uns selbst setzten, sondern auf Gott, der die Toten auferweckt, der uns aus solcher Todesnot errettet hat und erretten wird.","lehrtextReference":"2. Korinther 1,9-10"},"2026-06-12":{"text":"Der HERR, dein Gott, führt dich in ein gutes Land, ein Land, darin Bäche und Quellen sind und Wasser in der Tiefe.","reference":"5. Mose 8,7","translation":"Losung","lehrtext":"Gott hat die Macht, euch jede Gabe im Überfluss zu schenken. So habt ihr in jeder Hinsicht und zu jeder Zeit alles, was ihr zum Leben braucht. Und ihr habt immer noch mehr als genug, anderen reichlich Gutes zu tun.","lehrtextReference":"2. Korinther 9,8"},"2026-06-13":{"text":"Jünglinge werden müde und matt, und Männer straucheln und fallen; aber die auf den HERRN harren, kriegen neue Kraft, dass sie auffahren mit Flügeln wie Adler, dass sie laufen und nicht matt werden.","reference":"Jesaja 40,30-31","translation":"Losung","lehrtext":"Lasst uns laufen mit Geduld in dem Kampf, der uns bestimmt ist, und aufsehen zu Jesus, dem Anfänger und Vollender des Glaubens.","lehrtextReference":"Hebräer 12,1-2"},"2026-06-14":{"text":"Ich will ihnen ein Herz geben, dass sie mich erkennen sollen, dass ich der HERR bin.","reference":"Jeremia 24,7","translation":"Losung","lehrtext":"Die Jünger sprachen untereinander: Brannte nicht unser Herz in uns, da er mit uns redete auf dem Wege und uns die Schrift öffnete?","lehrtextReference":"Lukas 24,32"},"2026-06-15":{"text":"Siehe, Finsternis bedeckt das Erdreich und Dunkel die Völker; aber über dir geht auf der HERR, und seine Herrlichkeit erscheint über dir.","reference":"Jesaja 60,2","translation":"Losung","lehrtext":"/Jesus spricht:/ Ich bin das Licht der Welt. Wer mir nachfolgt, der wird nicht wandeln in der Finsternis, sondern wird das Licht des Lebens haben.","lehrtextReference":"Johannes 8,12"},"2026-06-16":{"text":"Wer den HERRN fürchtet, hat eine sichere Festung.","reference":"Sprüche 14,26","translation":"Losung","lehrtext":"Wer aus Gott geboren ist, den bewahrt er und der Böse tastet ihn nicht an.","lehrtextReference":"1. Johannes 5,18"},"2026-06-17":{"text":"Ich, der HERR, bin dein Heiland, und ich, der Mächtige, dein Erlöser.","reference":"Jesaja 60,16","translation":"Losung","lehrtext":"Wir haben unsre Hoffnung auf den lebendigen Gott gesetzt, welcher ist der Heiland aller Menschen, besonders der Gläubigen.","lehrtextReference":"1. Timotheus 4,10"},"2026-06-18":{"text":"Als der Pharao sah, dass Regen, Donner und Hagel aufhörten, versündigte er sich weiter und verhärtete sein Herz.","reference":"2. Mose 9,34","translation":"Losung","lehrtext":"Seht zu, Brüder und Schwestern, dass niemand unter euch ein böses, ungläubiges Herz habe und abfalle von dem lebendigen Gott.","lehrtextReference":"Hebräer 3,12"},"2026-06-19":{"text":"Du stellst meine Füße auf weiten Raum.","reference":"Psalm 31,9","translation":"Losung","lehrtext":"Zur Freiheit hat uns Christus befreit! So steht nun fest und lasst euch nicht wieder das Joch der Knechtschaft auflegen!","lehrtextReference":"Galater 5,1"},"2026-06-20":{"text":"Meine Lippen und meine Seele, die du erlöst hast, sollen fröhlich sein und dir lobsingen.","reference":"Psalm 71,23","translation":"Losung","lehrtext":"Zacharias forderte eine kleine Tafel und schrieb: Er heißt Johannes. Und sie wunderten sich alle. Und sogleich wurde sein Mund und seine Zunge aufgetan, und er redete und lobte Gott.","lehrtextReference":"Lukas 1,63-64"},"2026-06-21":{"text":"Ich rief zu dem HERRN in meiner Angst, und er antwortete mir.","reference":"Jona 2,3","translation":"Losung","lehrtext":"/Paulus schreibt:/ Der Herr hat zu mir gesagt: Lass dir an meiner Gnade genügen; denn meine Kraft vollendet sich in der Schwachheit.","lehrtextReference":"2. Korinther 12,9"},"2026-06-22":{"text":"So spricht der HERR: Ich gedenke der Treue deiner Jugend und der Liebe deiner Brautzeit, wie du mir folgtest in der Wüste, im Lande, da man nicht sät.","reference":"Jeremia 2,2","translation":"Losung","lehrtext":"Wir gehören ganz zu Christus – vorausgesetzt, wir halten bis zuletzt an der Zuversicht fest, die wir am Anfang hatten.","lehrtextReference":"Hebräer 3,14"},"2026-06-23":{"text":"Wir haben einen Gott, der da hilft, und den HERRN, der vom Tode errettet.","reference":"Psalm 68,21","translation":"Losung","lehrtext":"Gott hat den Herrn auferweckt und wird auch uns auferwecken durch seine Kraft.","lehrtextReference":"1. Korinther 6,14"},"2026-06-24":{"text":"HERR, zürne nicht so sehr und gedenke nicht ewig der Sünde! Sieh doch an, dass wir alle dein Volk sind!","reference":"Jesaja 64,8","translation":"Losung","lehrtext":"/Johannes der Täufer sprach:/ Bringt also Frucht, die der Umkehr entspricht!","lehrtextReference":"Matthäus 3,8"},"2026-06-25":{"text":"Seid getrost und lasst eure Hände nicht sinken; denn euer Werk hat seinen Lohn.","reference":"2. Chronik 15,7","translation":"Losung","lehrtext":"Da sprach sein Herr zu ihm: Recht so, du guter und treuer Knecht, du bist über wenigem treu gewesen, ich will dich über viel setzen; geh hinein zu deines Herrn Freude!","lehrtextReference":"Matthäus 25,21"},"2026-06-26":{"text":"Und du, Bethlehem Efrata, die du klein bist unter den Tausenden in Juda, aus dir soll mir der kommen, der in Israel Herr sei, dessen Ausgang von Anfang und von Ewigkeit her gewesen ist.","reference":"Micha 5,1","translation":"Losung","lehrtext":"Da Jesus geboren war zu Bethlehem in Judäa zur Zeit des Königs Herodes, siehe, da kamen Weise aus dem Morgenland nach Jerusalem und sprachen: Wo ist der neugeborene König der Juden? Wir haben seinen Stern aufgehen sehen und sind gekommen, ihn anzubeten.","lehrtextReference":"Matthäus 2,1-2"},"2026-06-27":{"text":"HERR, neige mein Herz nicht zum Bösen.","reference":"Psalm 141,4","translation":"Losung","lehrtext":"Einst wart ihr Finsternis, jetzt aber seid ihr Licht im Herrn. Lebt als Kinder des Lichts.","lehrtextReference":"Epheser 5,8"},"2026-06-28":{"text":"Du gibst meinen Schritten weiten Raum, und meine Knöchel wanken nicht.","reference":"2. Samuel 22,37","translation":"Losung","lehrtext":"Petrus aber sprach: Silber und Gold habe ich nicht; was ich aber habe, das gebe ich dir: Im Namen Jesu Christi von Nazareth steh auf und geh umher!","lehrtextReference":"Apostelgeschichte 3,6"},"2026-06-29":{"text":"Hasst das Böse und liebt das Gute, richtet das Recht auf im Tor, vielleicht wird der HERR, der Gott Zebaoth, gnädig sein.","reference":"Amos 5,15","translation":"Losung","lehrtext":"Zieht nicht mit den Ungläubigen an einem Strang. Wie passen Gerechtigkeit und Gesetzlosigkeit zusammen? Oder was hat das Licht mit der Finsternis zu tun?","lehrtextReference":"2. Korinther 6,14"},"2026-06-30":{"text":"Kehrt um, ihr abtrünnigen Kinder, spricht der HERR, denn ich bin euer Herr! Und ich will euch holen und will euch bringen nach Zion.","reference":"Jeremia 3,14","translation":"Losung","lehrtext":"Folgt nun dem Beispiel Gottes als geliebte Kinder, und führt euer Leben in der Liebe, wie auch Christus uns geliebt und sich für uns hingegeben hat als Gabe und Opfer für Gott.","lehrtextReference":"Epheser 5,1-2"},"2026-07-01":{"text":"Die Furcht des HERRN ist der Anfang der Erkenntnis.","reference":"Sprüche 1,7","translation":"Losung","lehrtext":"Erforscht euch selbst, ob ihr im Glauben steht; prüft euch selbst! Oder erkennt ihr an euch selbst nicht, dass Jesus Christus in euch ist?","lehrtextReference":"2. Korinther 13,5"},"2026-07-02":{"text":"HERR, verdirb dein Volk und dein Erbe nicht, das du durch deine große Kraft erlöst hast!","reference":"5. Mose 9,26","translation":"Losung","lehrtext":"/Der Engel sprach zu Josef:/ Maria wird einen Sohn gebären, dem sollst du den Namen Jesus geben, denn er wird sein Volk retten von ihren Sünden.","lehrtextReference":"Matthäus 1,21"},"2026-07-03":{"text":"Wenn der HERR spricht, so geschieht’s; wenn er gebietet, so steht’s da.","reference":"Psalm 33,9","translation":"Losung","lehrtext":"Jesus sprach zu dem Tauben: Hefata!, das heißt: Tu dich auf! Und sogleich taten sich seine Ohren auf, und die Fessel seiner Zunge wurde gelöst, und er redete richtig.","lehrtextReference":"Markus 7,34-35"},"2026-07-04":{"text":"Ich hörte die Stimme des Herrn, wie er sprach: Wen soll ich senden? Wer will unser Bote sein? Ich aber sprach: Hier bin ich, sende mich!","reference":"Jesaja 6,8","translation":"Losung","lehrtext":"So sind wir nun Botschafter an Christi statt, denn Gott ermahnt durch uns; so bitten wir nun an Christi statt: Lasst euch versöhnen mit Gott!","lehrtextReference":"2. Korinther 5,20"},"2026-07-05":{"text":"Du bist mein Gott von meiner Mutter Schoß an.","reference":"Psalm 22,11","translation":"Losung","lehrtext":"/Paulus schreibt an Timotheus:/ Dankbar erinnere ich mich daran, wie aufrichtig du glaubst. Es ist derselbe Glaube, der schon in deiner Großmutter Lois und in deiner Mutter Eunike wohnte. Und ich bin überzeugt, er wohnt auch in dir.","lehrtextReference":"2. Timotheus 1,5"},"2026-07-06":{"text":"So habt nun acht, dass ihr tut, wie euch der HERR, euer Gott, geboten hat, und weicht nicht, weder zur Rechten noch zur Linken.","reference":"5. Mose 5,32","translation":"Losung","lehrtext":"/Jesus spricht:/ Wer mir dienen will, der folge mir nach; und wo ich bin, da soll mein Diener auch sein.","lehrtextReference":"Johannes 12,26"},"2026-07-07":{"text":"Du hast mein Leben aus dem Verderben geführt, HERR, mein Gott!","reference":"Jona 2,7","translation":"Losung","lehrtext":"Petrus sprach zu ihm: Äneas, Jesus Christus macht dich gesund; steh auf und mach dir selber das Bett. Und sogleich stand er auf.","lehrtextReference":"Apostelgeschichte 9,34"},"2026-07-08":{"text":"Muss ich nicht das halten und reden, was mir der HERR in den Mund gibt?","reference":"4. Mose 23,12","translation":"Losung","lehrtext":"/Jesus spricht:/ Ein neues Gebot gebe ich euch, dass ihr euch untereinander liebt, wie ich euch geliebt habe, damit auch ihr einander lieb habt.","lehrtextReference":"Johannes 13,34"},"2026-07-09":{"text":"Es ist ein Gott im Himmel, der Geheimnisse offenbart.","reference":"Daniel 2,28","translation":"Losung","lehrtext":"Seinen Heiligen wollte Gott kundtun, was der herrliche Reichtum dieses Geheimnisses unter den Völkern ist, nämlich Christus in euch, die Hoffnung der Herrlichkeit.","lehrtextReference":"Kolosser 1,27"},"2026-07-10":{"text":"Alles, was dir vor die Hände kommt, es zu tun mit deiner Kraft, das tu.","reference":"Prediger 9,10","translation":"Losung","lehrtext":"Alles, was ihr tut mit Worten oder mit Werken, das tut alles im Namen des Herrn Jesus und dankt Gott, dem Vater, durch ihn.","lehrtextReference":"Kolosser 3,17"},"2026-07-11":{"text":"Seid stille und erkennet, dass ich Gott bin!","reference":"Psalm 46,11","translation":"Losung","lehrtext":"Die aber im Boot waren, fielen vor Jesus nieder und sprachen: Du bist wahrhaftig Gottes Sohn!","lehrtextReference":"Matthäus 14,33"},"2026-07-12":{"text":"HERR, du bist der Armen Schutz gewesen in der Trübsal, eine Zuflucht vor dem Ungewitter, ein Schatten vor der Hitze, wenn die Tyrannen wüten.","reference":"Jesaja 25,4","translation":"Losung","lehrtext":"Der Engel des Herrn erschien dem Josef im Traum in Ägypten und sprach: Steh auf, nimm das Kindlein und seine Mutter mit dir und zieh hin in das Land Israel; sie sind gestorben, die dem Kindlein nach dem Leben getrachtet haben.","lehrtextReference":"Matthäus 2,19-20"},"2026-07-13":{"text":"Der HERR kommt, das Erdreich zu richten. Er wird den Erdkreis richten mit Gerechtigkeit und die Völker, wie es recht ist.","reference":"Psalm 98,9","translation":"Losung","lehrtext":"/Jesus spricht:/ Mein Gericht ist gerecht; denn ich suche nicht meinen Willen, sondern den Willen dessen, der mich gesandt hat.","lehrtextReference":"Johannes 5,30"},"2026-07-14":{"text":"Siehe, da ist Gott der HERR! Er kommt gewaltig, und sein Arm wird herrschen.","reference":"Jesaja 40,10","translation":"Losung","lehrtext":"Ich hörte eine große Stimme von dem Thron her, die sprach: Siehe da, die Hütte Gottes bei den Menschen! Und er wird bei ihnen wohnen, und sie werden seine Völker sein, und er selbst, Gott mit ihnen, wird ihr Gott sein.","lehrtextReference":"Offenbarung 21,3"},"2026-07-15":{"text":"Mein Herz wendet sich gegen mich, all mein Mitleid ist entbrannt. Ich will nicht tun nach meinem grimmigen Zorn. Denn ich bin Gott und nicht ein Mensch, heilig in deiner Mitte.","reference":"Hosea 11,8.9","translation":"Losung","lehrtext":"Also hat Gott die Welt geliebt, dass er seinen eingeborenen Sohn gab, auf dass alle, die an ihn glauben, nicht verloren werden, sondern das ewige Leben haben.","lehrtextReference":"Johannes 3,16"},"2026-07-16":{"text":"Gott ist unsre Zuversicht und Stärke, eine Hilfe in den großen Nöten, die uns getroffen haben. Darum fürchten wir uns nicht.","reference":"Psalm 46,2-3","translation":"Losung","lehrtext":"Jesus spricht zu seiner Mutter: Frau, siehe, das ist dein Sohn! Danach spricht er zu dem Jünger: Siehe, das ist deine Mutter! Und von der Stunde an nahm sie der Jünger zu sich.","lehrtextReference":"Johannes 19,26-27"},"2026-07-17":{"text":"So schau nun vom Himmel und sieh herab von deiner heiligen, herrlichen Wohnung! Wo ist nun dein Eifer und deine Macht?","reference":"Jesaja 63,15","translation":"Losung","lehrtext":"/Jesus spricht:/ Ich will euch nicht als Waisen zurücklassen; ich komme zu euch.","lehrtextReference":"Johannes 14,18"},"2026-07-18":{"text":"Gott schuf sie als Mann und Frau und segnete sie und gab ihnen den Namen »Mensch«.","reference":"1. Mose 5,2","translation":"Losung","lehrtext":"Einer komme dem andern mit Ehrerbietung zuvor.","lehrtextReference":"Römer 12,10"},"2026-07-19":{"text":"Ach, HERR, strafe mich nicht in deinem Zorn und züchtige mich nicht in deinem Grimm!","reference":"Psalm 6,2","translation":"Losung","lehrtext":"Gott hat den, der von keiner Sünde wusste, für uns zur Sünde gemacht, auf dass wir in ihm die Gerechtigkeit würden, die vor Gott gilt.","lehrtextReference":"2. Korinther 5,21"},"2026-07-20":{"text":"Die Worte des HERRN sind lauter wie Silber, im Tiegel geschmolzen, geläutert siebenmal.","reference":"Psalm 12,7","translation":"Losung","lehrtext":"/Jesus spricht:/ Ich bin dazu geboren und in die Welt gekommen, dass ich die Wahrheit bezeuge. Wer aus der Wahrheit ist, der hört meine Stimme.","lehrtextReference":"Johannes 18,37"},"2026-07-21":{"text":"Freuet euch mit Jerusalem und seid fröhlich über die Stadt, alle, die ihr sie lieb habt! Freuet euch mit ihr, alle, die ihr über sie traurig gewesen seid.","reference":"Jesaja 66,10","translation":"Losung","lehrtext":"Als Jesus schon nahe am Abhang des Ölbergs war, fing die ganze Menge der Jünger an, mit Freuden Gott zu loben mit lauter Stimme über alle Taten, die sie gesehen hatten.","lehrtextReference":"Lukas 19,37"},"2026-07-22":{"text":"Der HERR sprach zu Mose: Das ganze Volk, in dessen Mitte du bist, soll des HERRN Werk sehen.","reference":"2. Mose 34,10","translation":"Losung","lehrtext":"Das Volk verwunderte sich, als sie sahen, dass die Stummen redeten, die Verkrüppelten gesund waren, die Lahmen gingen und die Blinden sahen; und sie priesen den Gott Israels.","lehrtextReference":"Matthäus 15,31"},"2026-07-23":{"text":"Ich liege gefangen und kann nicht heraus, mein Auge vergeht vor Elend. HERR, ich rufe zu dir täglich.","reference":"Psalm 88,9-10","translation":"Losung","lehrtext":"Es wurde ein Mann herbeigetragen, der war gelähmt von Mutterleibe an; den setzte man täglich vor das Tor des Tempels, das da heißt das Schöne, damit er um Almosen bettelte bei denen, die in den Tempel gingen.","lehrtextReference":"Apostelgeschichte 3,2"},"2026-07-24":{"text":"Gott tut große Dinge, die nicht zu erforschen, und Wunder, die nicht zu zählen sind.","reference":"Hiob 9,10","translation":"Losung","lehrtext":"Wir wissen, dass er, der Jesus, den Herrn, auferweckt hat, mit Jesus auch uns auferwecken und mit euch vor sich hinstellen wird.","lehrtextReference":"2. Korinther 4,14"},"2026-07-25":{"text":"Ein Vater der Waisen und ein Helfer der Witwen ist Gott in seiner heiligen Wohnung, ein Gott, der die Einsamen nach Hause bringt, der die Gefangenen herausführt, dass es ihnen wohlgehe.","reference":"Psalm 68,6-7","translation":"Losung","lehrtext":"Gelobt sei Gott, der Vater unseres Herrn Jesus Christus, der Vater der Barmherzigkeit und Gott allen Trostes.","lehrtextReference":"2. Korinther 1,3"},"2026-07-26":{"text":"Josef sprach zu seinen Brüdern: Zankt nicht auf dem Wege!","reference":"1. Mose 45,24","translation":"Losung","lehrtext":"Selig sind, die Frieden stiften; denn sie werden Gottes Kinder heißen.","lehrtextReference":"Matthäus 5,9"},"2026-07-27":{"text":"Die Augen des HERRN merken auf die Gerechten und seine Ohren auf ihr Schreien.","reference":"Psalm 34,16","translation":"Losung","lehrtext":"Als Pilatus auf dem Richterstuhl saß, schickte seine Frau zu ihm und ließ ihm sagen: Habe du nichts zu schaffen mit diesem Gerechten; denn ich habe heute viel erlitten im Traum um seinetwillen.","lehrtextReference":"Matthäus 27,19"},"2026-07-28":{"text":"Täglich rühmen wir uns Gottes und preisen deinen Namen ewiglich.","reference":"Psalm 44,9","translation":"Losung","lehrtext":"Singt und musiziert dem Herrn aus vollem Herzen.","lehrtextReference":"Epheser 5,19"},"2026-07-29":{"text":"Meine Tränen sind meine Speise Tag und Nacht, weil man täglich zu mir sagt: Wo ist nun dein Gott?","reference":"Psalm 42,4","translation":"Losung","lehrtext":"/Paulus schreibt:/ Dass ich meine Fesseln für Christus trage, das ist im ganzen Prätorium und bei allen andern offenbar geworden, und die meisten Brüder in dem Herrn haben durch meine Gefangenschaft Zuversicht gewonnen und sind umso kühner geworden, das Wort zu reden ohne Scheu.","lehrtextReference":"Philipper 1,13-14"},"2026-07-30":{"text":"Die vom Volk, die ihren Gott kennen, werden stark sein und danach handeln.","reference":"Daniel 11,32","translation":"Losung","lehrtext":"Das sagt der Heilige, der Wahrhaftige: Weil du mein Wort von der Geduld bewahrt hast, will auch ich dich bewahren vor der Stunde der Versuchung.","lehrtextReference":"Offenbarung 3,7.10"},"2026-07-31":{"text":"Siehe, ich will mein Volk schmelzen und prüfen.","reference":"Jeremia 9,6","translation":"Losung","lehrtext":"Betet, dass ihr nicht in Anfechtung fallt!","lehrtextReference":"Lukas 22,40"},"2026-08-01":{"text":"Du sollst nicht begehren deines Nächsten Haus noch alles, was sein ist.","reference":"5. Mose 5,21","translation":"Losung","lehrtext":"Lasst euer Leben vom Geist Gottes bestimmt sein und richtet es danach aus. Dann werdet ihr nicht euren selbstsüchtigen Wünschen nachgeben.","lehrtextReference":"Galater 5,16"},"2026-08-02":{"text":"Die Völker hören auf Zeichendeuter und Wahrsager; dir aber hat der HERR, dein Gott, so etwas verwehrt.","reference":"5. Mose 18,14","translation":"Losung","lehrtext":"Da ihr Gott erkannt habt, ja vielmehr von Gott erkannt seid, wie wendet ihr euch dann wieder den schwachen und dürftigen Mächten zu, denen ihr von Neuem dienen wollt?","lehrtextReference":"Galater 4,9"},"2026-08-03":{"text":"Erkennet, dass der HERR Gott ist!","reference":"Psalm 100,3","translation":"Losung","lehrtext":"Die Apostel und die Brüder und Schwestern priesen Gott und sprachen: Nun hat Gott also auch den anderen Völkern die Umkehr zum Leben gewährt.","lehrtextReference":"Apostelgeschichte 11,18"},"2026-08-04":{"text":"/Der HERR spricht:/ Ihr habt gesehen, wie ich euch getragen habe auf Adlerflügeln und euch zu mir gebracht.","reference":"2. Mose 19,4","translation":"Losung","lehrtext":"Auf Gott hoffen wir, er werde uns auch hinfort erretten.","lehrtextReference":"2. Korinther 1,10"},"2026-08-05":{"text":"Gideon sprach zu dem Engel des HERRN: Ist der HERR mit uns, warum ist uns dann das alles widerfahren?","reference":"Richter 6,13","translation":"Losung","lehrtext":"Ihr werdet euch freuen, die ihr jetzt eine kleine Zeit, wenn es sein soll, traurig seid in mancherlei Anfechtungen, auf dass euer Glaube bewährt und viel kostbarer befunden werde als vergängliches Gold.","lehrtextReference":"1. Petrus 1,6-7"},"2026-08-06":{"text":"Du machst fröhlich, was da lebet im Osten wie im Westen.","reference":"Psalm 65,9","translation":"Losung","lehrtext":"Der Kerkermeister freute sich mit seinem ganzen Hause, dass er zum Glauben an Gott gekommen war.","lehrtextReference":"Apostelgeschichte 16,34"},"2026-08-07":{"text":"Jauchze, du Tochter Zion! Frohlocke, Israel! Freue dich und sei fröhlich von ganzem Herzen, du Tochter Jerusalem! Denn der HERR hat deine Strafe weggenommen.","reference":"Zefanja 3,14-15","translation":"Losung","lehrtext":"Christus ist gekommen und hat im Evangelium Frieden verkündigt euch, die ihr fern wart, und Frieden denen, die nahe waren.","lehrtextReference":"Epheser 2,17"},"2026-08-08":{"text":"Du bist der Gott, der mir hilft; täglich harre ich auf dich.","reference":"Psalm 25,5","translation":"Losung","lehrtext":"Bittet, so wird euch gegeben; suchet, so werdet ihr finden; klopfet an, so wird euch aufgetan.","lehrtextReference":"Matthäus 7,7"},"2026-08-09":{"text":"Siehe, was ich früher verkündigt habe, ist gekommen. So verkündige ich auch Neues; ehe denn es sprosst, lasse ich’s euch hören.","reference":"Jesaja 42,9","translation":"Losung","lehrtext":"Der Menschensohn ist’s, der den guten Samen sät. Der Acker ist die Welt.","lehrtextReference":"Matthäus 13,37-38"},"2026-08-10":{"text":"Der HERR hat seinen Thron im Himmel errichtet, und sein Reich herrscht über alles.","reference":"Psalm 103,19","translation":"Losung","lehrtext":"Wenn der Menschensohn kommen wird in seiner Herrlichkeit und alle Engel mit ihm, dann wird er sich setzen auf den Thron seiner Herrlichkeit, und alle Völker werden vor ihm versammelt werden.","lehrtextReference":"Matthäus 25,31-32"},"2026-08-11":{"text":"Tu mir kund den Weg, den ich gehen soll; denn mich verlangt nach dir.","reference":"Psalm 143,8","translation":"Losung","lehrtext":"Simon Petrus antwortete Jesus: Herr, wohin sollen wir gehen? Du hast Worte des ewigen Lebens; und wir haben geglaubt und erkannt: Du bist der Heilige Gottes.","lehrtextReference":"Johannes 6,68-69"},"2026-08-12":{"text":"Wie sich ein Vater über Kinder erbarmt, so erbarmt sich der HERR über die, die ihn fürchten.","reference":"Psalm 103,13","translation":"Losung","lehrtext":"Weil ihr nun Kinder seid, hat Gott den Geist seines Sohnes gesandt in unsre Herzen, der da ruft: Abba, lieber Vater!","lehrtextReference":"Galater 4,6"},"2026-08-13":{"text":"Er gedenkt ewiglich an seinen Bund, an das Wort, das er verheißen hat für tausend Geschlechter.","reference":"Psalm 105,8","translation":"Losung","lehrtext":"Auf alle Gottesverheißungen ist in Jesus Christus das Ja; darum sprechen wir auch durch ihn das Amen, Gott zur Ehre.","lehrtextReference":"2. Korinther 1,20"},"2026-08-14":{"text":"Leben und Wohltat hast du an mir getan, und deine Obhut hat meinen Odem bewahrt.","reference":"Hiob 10,12","translation":"Losung","lehrtext":"Er antwortete: Der Mensch, der Jesus heißt, machte einen Brei und strich ihn auf meine Augen und sprach: Geh zum Teich Siloah und wasche dich! Ich ging hin und wusch mich und wurde sehend.","lehrtextReference":"Johannes 9,11"},"2026-08-15":{"text":"Kommt, lasst uns anbeten und knien und niederfallen vor dem HERRN, der uns gemacht hat.","reference":"Psalm 95,6","translation":"Losung","lehrtext":"Der Samariter fiel nieder auf sein Angesicht zu Jesu Füßen und dankte ihm.","lehrtextReference":"Lukas 17,16"},"2026-08-16":{"text":"In meinem Zorn habe ich dich geschlagen, aber in meiner Gnade erbarme ich mich über dich.","reference":"Jesaja 60,10","translation":"Losung","lehrtext":"Gott hat uns nicht bestimmt zum Zorn, sondern dazu, die Seligkeit zu besitzen durch unsern Herrn Jesus Christus.","lehrtextReference":"1. Thessalonicher 5,9"},"2026-08-17":{"text":"Der HERR hat das Recht lieb.","reference":"Psalm 37,28","translation":"Losung","lehrtext":"Jesus sprach: Gebt dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist!","lehrtextReference":"Markus 12,17"},"2026-08-18":{"text":"Gott der HERR hat mir das Ohr geöffnet. Und ich bin nicht ungehorsam und weiche nicht zurück.","reference":"Jesaja 50,5","translation":"Losung","lehrtext":"Maria setzte sich dem Herrn zu Füßen und hörte seiner Rede zu.","lehrtextReference":"Lukas 10,39"},"2026-08-19":{"text":"Der Tag des HERRN kommt und ist nahe.","reference":"Joel 2,1","translation":"Losung","lehrtext":"Darum seid auch ihr bereit! Denn der Menschensohn kommt zu einer Stunde, da ihr’s nicht meint.","lehrtextReference":"Matthäus 24,44"},"2026-08-20":{"text":"Meine Wohnung soll unter ihnen sein, und ich will ihr Gott sein, und sie sollen mein Volk sein.","reference":"Hesekiel 37,27","translation":"Losung","lehrtext":"Wie viele ihn aufnahmen, denen gab er Macht, Gottes Kinder zu werden: denen, die an seinen Namen glauben.","lehrtextReference":"Johannes 1,12"},"2026-08-21":{"text":"Die Erlösten des HERRN werden heimkehren. Wonne und Freude werden sie ergreifen, aber Trauern und Seufzen wird von ihnen fliehen.","reference":"Jesaja 51,11","translation":"Losung","lehrtext":"Ihr werdet euch freuen mit unaussprechlicher und herrlicher Freude, wenn ihr das Ziel eures Glaubens erlangt, nämlich der Seelen Seligkeit.","lehrtextReference":"1. Petrus 1,8-9"},"2026-08-22":{"text":"Meine Zunge soll singen von deinem Wort; denn alle deine Gebote sind gerecht.","reference":"Psalm 119,172","translation":"Losung","lehrtext":"Aus #einem# Munde kommt Loben und Fluchen. Das soll nicht so sein, meine Brüder und Schwestern.","lehrtextReference":"Jakobus 3,10"},"2026-08-23":{"text":"Sie litten keinen Durst, als der HERR sie leitete in der Wüste. Er ließ ihnen Wasser aus dem Felsen fließen.","reference":"Jesaja 48,21","translation":"Losung","lehrtext":"Wer euch einen Becher Wasser zu trinken gibt deshalb, weil ihr Christus angehört, wahrlich, ich sage euch: Er wird nicht um seinen Lohn kommen.","lehrtextReference":"Markus 9,41"},"2026-08-24":{"text":"/Gott spricht:/ Von nun an lasse ich dich Neues hören und Verborgenes, das du nicht wusstest.","reference":"Jesaja 48,6","translation":"Losung","lehrtext":"Als die Athener von der Auferstehung der Toten hörten, begannen die einen zu spotten; die andern aber sprachen: Wir wollen dich darüber ein andermal weiterhören.","lehrtextReference":"Apostelgeschichte 17,32"},"2026-08-25":{"text":"Ich rufe zu Gott, dem Allerhöchsten, zu Gott, der meine Sache zum guten Ende führt.","reference":"Psalm 57,3","translation":"Losung","lehrtext":"/Jesus spricht:/ Bisher habt ihr um nichts gebeten in meinem Namen. Bittet, so werdet ihr empfangen, auf dass eure Freude vollkommen sei.","lehrtextReference":"Johannes 16,24"},"2026-08-26":{"text":"/Der HERR spricht:/ Er liebt mich, darum will ich ihn erretten.","reference":"Psalm 91,14","translation":"Losung","lehrtext":"/Jesus betete:/ Ich bitte nicht, dass du sie aus der Welt nimmst, sondern dass du sie bewahrst vor dem Bösen.","lehrtextReference":"Johannes 17,15"},"2026-08-27":{"text":"Mein Volk soll meiner Gaben die Fülle haben, spricht der HERR.","reference":"Jeremia 31,14","translation":"Losung","lehrtext":"Mein Gott wird all eurem Mangel abhelfen nach seinem Reichtum in Herrlichkeit in Christus Jesus.","lehrtextReference":"Philipper 4,19"},"2026-08-28":{"text":"HERR, führe meine Sache und erlöse mich; erquicke mich durch dein Wort.","reference":"Psalm 119,154","translation":"Losung","lehrtext":"Jesus sprach: Sei getrost, meine Tochter, dein Glaube hat dir geholfen. Und die Frau wurde gesund zu derselben Stunde.","lehrtextReference":"Matthäus 9,22"},"2026-08-29":{"text":"Ich bin arm und elend; der HERR aber sorgt für mich.","reference":"Psalm 40,18","translation":"Losung","lehrtext":"/Paulus schreibt:/ Mir ist alles und jedes vertraut: beides, satt sein und hungern, beides, Überfluss haben und Mangel leiden; ich vermag alles durch den, der mich mächtig macht.","lehrtextReference":"Philipper 4,12-13"},"2026-08-30":{"text":"Der Engel des HERRN rührte Elia an und sprach: Steh auf und iss! Denn du hast einen weiten Weg vor dir.","reference":"1. Könige 19,7","translation":"Losung","lehrtext":"/Paulus sprach im Sturmwind:/ Ich ermahne euch, etwas zu essen; denn das dient zu eurer Rettung; es wird keinem von euch ein Haar vom Haupt fallen.","lehrtextReference":"Apostelgeschichte 27,34"},"2026-08-31":{"text":"/Jakob gelobte Gott:/ Von allem, was du mir gibst, will ich dir den Zehnten geben.","reference":"1. Mose 28,22","translation":"Losung","lehrtext":"Einen fröhlichen Geber hat Gott lieb.","lehrtextReference":"2. Korinther 9,7"},"2026-09-01":{"text":"So spricht der HERR, dein Erlöser, der dich von Mutterleibe bereitet hat: Ich bin der HERR, der alles schafft, der den Himmel ausbreitet allein und die Erde fest macht ohne Gehilfen.","reference":"Jesaja 44,24","translation":"Losung","lehrtext":"Jedes Haus wird von jemandem erbaut; der aber alles erbaut hat, das ist Gott.","lehrtextReference":"Hebräer 3,4"},"2026-09-02":{"text":"So spricht der HERR Zebaoth: Wer euch antastet, der tastet seinen Augapfel an.","reference":"Sacharja 2,12","translation":"Losung","lehrtext":"Was gering ist vor der Welt und was verachtet ist, das hat Gott erwählt, was nichts ist, damit er zunichtemache, was etwas ist.","lehrtextReference":"1. Korinther 1,28"},"2026-09-03":{"text":"Auf dich, HERR, sehen meine Augen; ich traue auf dich, gib mich nicht in den Tod dahin.","reference":"Psalm 141,8","translation":"Losung","lehrtext":"Tod, wo ist dein Sieg? Tod, wo ist dein Stachel? Gott aber sei Dank, der uns den Sieg gibt durch unsern Herrn Jesus Christus!","lehrtextReference":"1. Korinther 15,55.57"},"2026-09-04":{"text":"Vom Aufgang der Sonne bis zu ihrem Niedergang sei gelobet der Name des HERRN!","reference":"Psalm 113,3","translation":"Losung","lehrtext":"Betet an den, der gemacht hat Himmel und Erde und Meer und die Wasserquellen!","lehrtextReference":"Offenbarung 14,7"},"2026-09-05":{"text":"Keiner wird zuschanden, der auf dich harret; aber zuschanden werden die leichtfertigen Verächter.","reference":"Psalm 25,3","translation":"Losung","lehrtext":"Die auf dem Fels sind die, welche das Wort hören und freudig aufnehmen. Doch sie haben keine Wurzeln: Eine Zeit lang glauben sie, in der Zeit der Versuchung aber fallen sie ab.","lehrtextReference":"Lukas 8,13"},"2026-09-06":{"text":"Fürchtet euch nicht, wenn euch die Leute schmähen, und entsetzt euch nicht, wenn sie euch verhöhnen!","reference":"Jesaja 51,7","translation":"Losung","lehrtext":"Gott hat uns nicht gegeben den Geist der Furcht, sondern der Kraft und der Liebe und der Besonnenheit.","lehrtextReference":"2. Timotheus 1,7"},"2026-09-07":{"text":"Ich preise dich, HERR; denn du hast mich aus der Tiefe gezogen.","reference":"Psalm 30,2","translation":"Losung","lehrtext":"Jesus ergriff das Kind bei der Hand und sprach zu ihm: Talita kum! – das heißt übersetzt: Mädchen, ich sage dir, steh auf! Und sogleich stand das Mädchen auf und ging umher.","lehrtextReference":"Markus 5,41-42"},"2026-09-08":{"text":"Wer auf den HERRN hofft, den wird die Güte umfangen.","reference":"Psalm 32,10","translation":"Losung","lehrtext":"Die Gnade des Herrn Jesus sei mit allen!","lehrtextReference":"Offenbarung 22,21"},"2026-09-09":{"text":"Unser Gott wandte den Fluch in einen Segen.","reference":"Nehemia 13,2","translation":"Losung","lehrtext":"Christus hat uns freigekauft vom Fluch des Gesetzes, indem er für uns zum Fluch geworden ist - es steht nämlich geschrieben: Verflucht ist jeder, der am Holz hängt.","lehrtextReference":"Galater 3,13"},"2026-09-10":{"text":"Ein Geduldiger ist besser als ein Starker und wer sich selbst beherrscht, besser als einer, der Städte einnimmt.","reference":"Sprüche 16,32","translation":"Losung","lehrtext":"Hier ist von den Heiligen Standhaftigkeit gefordert, hier sind gefordert, die festhalten an den Geboten Gottes und am Glauben an Jesus!","lehrtextReference":"Offenbarung 14,12"},"2026-09-11":{"text":"David und ganz Israel tanzten mit aller Macht vor Gott her, mit Liedern, mit Harfen, mit Psaltern, mit Pauken, mit Zimbeln und mit Trompeten.","reference":"1. Chronik 13,8","translation":"Losung","lehrtext":"Seid allezeit fröhlich!","lehrtextReference":"1. Thessalonicher 5,16"},"2026-09-12":{"text":"Hüte dich nur und bewahre deine Seele gut, dass du nicht vergisst, was deine Augen gesehen haben.","reference":"5. Mose 4,9","translation":"Losung","lehrtext":"Maria Magdalena geht und verkündigt den Jüngern: »Ich habe den Herrn gesehen«, und was er zu ihr gesagt habe.","lehrtextReference":"Johannes 20,18"},"2026-09-13":{"text":"Der HERR ist des Armen Schutz, ein Schutz in Zeiten der Not.","reference":"Psalm 9,10","translation":"Losung","lehrtext":"Ein reiner und unbefleckter Gottesdienst vor Gott, dem Vater, ist der: die Waisen und Witwen in ihrer Trübsal besuchen.","lehrtextReference":"Jakobus 1,27"},"2026-09-14":{"text":"Siehe, es kommt die Zeit, spricht der HERR, da will ich mit dem Hause Israel und mit dem Hause Juda einen neuen Bund schließen.","reference":"Jeremia 31,31","translation":"Losung","lehrtext":"/Petrus sprach:/ Euch und euren Kindern gilt diese Verheißung und allen, die fern sind, so viele der Herr, unser Gott, herzurufen wird.","lehrtextReference":"Apostelgeschichte 2,39"},"2026-09-15":{"text":"Der HERR wird für euch streiten, und ihr werdet stille sein.","reference":"2. Mose 14,14","translation":"Losung","lehrtext":"Wenn sie euch hinführen und überantworten werden, so sorgt euch nicht vorher, was ihr reden sollt; sondern was euch in jener Stunde gegeben wird, das redet. Denn ihr seid’s nicht, die da reden, sondern der Heilige Geist.","lehrtextReference":"Markus 13,11"},"2026-09-16":{"text":"Deine Güte, HERR, sei über uns, wie wir auf dich hoffen.","reference":"Psalm 33,22","translation":"Losung","lehrtext":"/Jesus spricht:/ Ich bin die Tür. Wenn jemand durch mich hineingeht, wird er gerettet werden.","lehrtextReference":"Johannes 10,9"},"2026-09-17":{"text":"Führe mich aus dem Kerker, dass ich preise deinen Namen.","reference":"Psalm 142,8","translation":"Losung","lehrtext":"Petrus wurde im Gefängnis festgehalten; aber die Gemeinde betete ohne Aufhören für ihn zu Gott.","lehrtextReference":"Apostelgeschichte 12,5"},"2026-09-18":{"text":"Ihr sollt einer mit dem andern reden: »Was hat der HERR geantwortet?«, und: »Was hat der HERR gesagt?«","reference":"Jeremia 23,35","translation":"Losung","lehrtext":"Petrus dachte an das Wort, das Jesus gesagt hatte: Ehe der Hahn kräht, wirst du mich dreimal verleugnen. Und er ging hinaus und weinte bitterlich.","lehrtextReference":"Matthäus 26,75"},"2026-09-19":{"text":"/Gott spricht:/ Ich will nicht immerdar hadern und nicht ewiglich zürnen.","reference":"Jesaja 57,16","translation":"Losung","lehrtext":"Wenn jemand sündigt, so haben wir einen Fürsprecher bei dem Vater, Jesus Christus, der gerecht ist.","lehrtextReference":"1. Johannes 2,1"},"2026-09-20":{"text":"Die dein Heil lieben, lass allewege sagen: Der HERR sei hoch gelobt!","reference":"Psalm 40,17","translation":"Losung","lehrtext":"/Paulus schreibt:/ Der Herr wird mich erlösen von allem Übel und mich retten in sein himmlisches Reich. Ihm sei Ehre von Ewigkeit zu Ewigkeit! Amen.","lehrtextReference":"2. Timotheus 4,18"},"2026-09-21":{"text":"Nun hat der HERR mir gegeben, was ich von ihm erbeten habe.","reference":"1. Samuel 1,27","translation":"Losung","lehrtext":"Elisabeths Nachbarn und Verwandten hörten, dass der Herr große Barmherzigkeit an ihr getan hatte, und freuten sich mit ihr.","lehrtextReference":"Lukas 1,58"},"2026-09-22":{"text":"Sie gaben’s dem HERRN freiwillig von ganzem Herzen.","reference":"1. Chronik 29,9","translation":"Losung","lehrtext":"Josef hatte einen Acker und verkaufte ihn und brachte das Geld und legte es den Aposteln zu Füßen.","lehrtextReference":"Apostelgeschichte 4,37"},"2026-09-23":{"text":"Lobe den HERRN, meine Seele, und vergiss nicht, was er dir Gutes getan hat.","reference":"Psalm 103,2","translation":"Losung","lehrtext":"Sagt Dank Gott, dem Vater, allezeit für alles, im Namen unseres Herrn Jesus Christus.","lehrtextReference":"Epheser 5,20"},"2026-09-24":{"text":"Die Völker, die um euch her übrig geblieben sind, sollen erfahren, dass ich der HERR bin, der da baut, was niedergerissen ist, und pflanzt, was verheert war.","reference":"Hesekiel 36,36","translation":"Losung","lehrtext":"/Der Seher Johannes schreibt:/ Siehe, eine große Schar, die niemand zählen konnte, aus allen Nationen und Stämmen und Völkern und Sprachen; die riefen mit großer Stimme: Das Heil ist bei unserm Gott, der auf dem Thron sitzt, und bei dem Lamm!","lehrtextReference":"Offenbarung 7,9.10"},"2026-09-25":{"text":"Wohl dem Volk, dessen Gott der HERR ist!","reference":"Psalm 144,15","translation":"Losung","lehrtext":"Es ist über alle derselbe Herr, reich für alle, die ihn anrufen.","lehrtextReference":"Römer 10,12"},"2026-09-26":{"text":"Seine Herrschaft wird sein von einem Meer bis zum andern und bis an die Enden der Erde.","reference":"Sacharja 9,10","translation":"Losung","lehrtext":"Es wird gepredigt werden dies Evangelium vom Reich in der ganzen Welt zum Zeugnis für alle Völker.","lehrtextReference":"Matthäus 24,14"},"2026-09-27":{"text":"Der HERR verstößt sein Volk nicht um seines großen Namens willen.","reference":"1. Samuel 12,22","translation":"Losung","lehrtext":"/Jesus betete:/ Ich habe ihnen deinen Namen kundgetan und werde ihn kundtun, damit die Liebe, mit der du mich liebst, in ihnen sei und ich in ihnen.","lehrtextReference":"Johannes 17,26"},"2026-09-28":{"text":"Ich will dich mir verloben auf ewig, ich will dich mir verloben in Gerechtigkeit und Recht, in Gnade und Barmherzigkeit.","reference":"Hosea 2,21","translation":"Losung","lehrtext":"/Jesus spricht:/ Nicht ihr habt mich erwählt, sondern ich habe euch erwählt.","lehrtextReference":"Johannes 15,16"},"2026-09-29":{"text":"Gelobet sei der Name Gottes von Ewigkeit zu Ewigkeit, denn ihm gehören Weisheit und Stärke!","reference":"Daniel 2,20","translation":"Losung","lehrtext":"Amen, Lob und Ehre und Weisheit und Dank und Preis und Kraft und Stärke sei unserm Gott von Ewigkeit zu Ewigkeit!","lehrtextReference":"Offenbarung 7,12"},"2026-09-30":{"text":"Wenn ihr den HERRN sucht, wird er sich von euch finden lassen.","reference":"2. Chronik 15,2","translation":"Losung","lehrtext":"Die Frau spricht zu Jesus: Ich weiß, dass der Messias kommt, der da Christus heißt. Wenn dieser kommt, wird er uns alles verkündigen. Jesus spricht zu ihr: Ich bin’s, der mit dir redet.","lehrtextReference":"Johannes 4,25-26"},"2026-10-01":{"text":"Gott, der du uns viel Angst und Not hast erfahren lassen, du wirst uns wieder beleben.","reference":"Psalm 71,20","translation":"Losung","lehrtext":"Der Herr weiß die Frommen aus der Versuchung zu erretten.","lehrtextReference":"2. Petrus 2,9"},"2026-10-02":{"text":"Rede, HERR, denn dein Knecht hört.","reference":"1. Samuel 3,9","translation":"Losung","lehrtext":"/Jesus spricht:/ Wer diese meine Rede hört und tut sie, der gleicht einem klugen Mann, der sein Haus auf Fels baute.","lehrtextReference":"Matthäus 7,24"},"2026-10-03":{"text":"Dies Volk naht mir mit seinem Munde und ehrt mich mit seinen Lippen, aber ihr Herz ist fern von mir.","reference":"Jesaja 29,13","translation":"Losung","lehrtext":"/Jesus spricht:/ Nicht was zum Mund hineingeht, macht den Menschen unrein; sondern was aus dem Mund herauskommt, das macht den Menschen unrein.","lehrtextReference":"Matthäus 15,11"},"2026-10-04":{"text":"Steht auf! Lobet den HERRN, euren Gott, von Ewigkeit zu Ewigkeit! Und man lobe seinen herrlichen Namen, der erhaben ist über allen Preis und Ruhm!","reference":"Nehemia 9,5","translation":"Losung","lehrtext":"Ob ihr nun esst oder trinkt oder was ihr auch tut, das tut alles zu Gottes Ehre.","lehrtextReference":"1. Korinther 10,31"},"2026-10-05":{"text":"Ich habe es gewagt, zu meinem Herrn zu reden, obwohl ich Staub und Asche bin.","reference":"1. Mose 18,27","translation":"Losung","lehrtext":"Die Frau entgegnete: Ja, Herr! Aber die Hunde fressen doch die Krümel, die vom Tisch ihrer Herren herunterfallen. Darauf antwortete Jesus: Frau, dein Glaube ist groß! Was du willst, soll dir geschehen!","lehrtextReference":"Matthäus 15,27-28"},"2026-10-06":{"text":"Lass mich nicht zuschanden werden, denn ich traue auf dich!","reference":"Psalm 25,20","translation":"Losung","lehrtext":"/Jesus Christus spricht:/ Ich lebe, und ihr sollt auch leben.","lehrtextReference":"Johannes 14,19"},"2026-10-07":{"text":"Suchet das Gute und nicht das Böse, auf dass ihr lebet.","reference":"Amos 5,14","translation":"Losung","lehrtext":"Seht zu, dass keiner dem andern Böses mit Bösem vergelte, sondern jagt allezeit dem Guten nach, füreinander und für jedermann.","lehrtextReference":"1. Thessalonicher 5,15"},"2026-10-08":{"text":"Die Weissagung wird ja noch erfüllt werden zu ihrer Zeit. Wenn sie sich auch hinzieht, so harre ihrer.","reference":"Habakuk 2,3","translation":"Losung","lehrtext":"Siehe, der Bauer wartet auf die kostbare Frucht der Erde und ist dabei geduldig, bis sie empfange den Frühregen und Spätregen.","lehrtextReference":"Jakobus 5,7"},"2026-10-09":{"text":"Siehe, Gott der HERR hilft mir; wer will mich verdammen?","reference":"Jesaja 50,9","translation":"Losung","lehrtext":"Christus Jesus ist hier, der gestorben ist, ja mehr noch, der auch auferweckt ist, der zur Rechten Gottes ist und für uns eintritt.","lehrtextReference":"Römer 8,34"},"2026-10-10":{"text":"Ist denn die Hand des HERRN zu kurz?","reference":"4. Mose 11,23","translation":"Losung","lehrtext":"Die Jünger sprachen untereinander: Wer ist der, dass ihm Wind und Meer gehorsam sind!","lehrtextReference":"Markus 4,41"},"2026-10-11":{"text":"Gideon sprach: Ich will nicht Herrscher über euch sein, sondern der HERR soll Herrscher über euch sein.","reference":"Richter 8,23","translation":"Losung","lehrtext":"Thomas sprach zu Jesus: Mein Herr und mein Gott!","lehrtextReference":"Johannes 20,28"},"2026-10-12":{"text":"Ich gedenke an die früheren Zeiten; ich sinne nach über all deine Taten und spreche von den Werken deiner Hände.","reference":"Psalm 143,5","translation":"Losung","lehrtext":"/Maria sprach:/ Seine Barmherzigkeit währet für und für bei denen, die ihn fürchten.","lehrtextReference":"Lukas 1,50"},"2026-10-13":{"text":"Auch wir wollen dem HERRN dienen; denn er ist unser Gott.","reference":"Josua 24,18","translation":"Losung","lehrtext":"Jesus sah einen Zöllner mit Namen Levi am Zoll sitzen und sprach zu ihm: Folge mir nach! Und er verließ alles, stand auf und folgte ihm nach.","lehrtextReference":"Lukas 5,27-28"},"2026-10-14":{"text":"Dem Gerechten muss das Licht immer wieder aufgehen und Freude den aufrichtigen Herzen.","reference":"Psalm 97,11","translation":"Losung","lehrtext":"Wenn du ein Mahl machst, so lade Arme, Verkrüppelte, Lahme und Blinde ein, dann wirst du selig sein, denn sie haben nichts, um es dir zu vergelten.","lehrtextReference":"Lukas 14,13-14"},"2026-10-15":{"text":"Der HERR ist freundlich dem, der auf ihn harrt, und dem Menschen, der nach ihm fragt.","reference":"Klagelieder 3,25","translation":"Losung","lehrtext":"Siehe, ich stehe vor der Tür und klopfe an. Wenn jemand meine Stimme hören wird und die Tür auftun, zu dem werde ich hineingehen und das Abendmahl mit ihm halten und er mit mir.","lehrtextReference":"Offenbarung 3,20"},"2026-10-16":{"text":"Gottes Hilfe ist nahe denen, die ihn fürchten, dass Güte und Treue einander begegnen, Gerechtigkeit und Friede sich küssen.","reference":"Psalm 85,10.11","translation":"Losung","lehrtext":"Die Frucht des Lichts ist lauter Güte und Gerechtigkeit und Wahrheit.","lehrtextReference":"Epheser 5,9"},"2026-10-17":{"text":"Schafft Recht und Gerechtigkeit und errettet den Beraubten von des Frevlers Hand und bedrängt nicht die Fremdlinge, Waisen und Witwen und tut niemand Gewalt an.","reference":"Jeremia 22,3","translation":"Losung","lehrtext":"Einer trage des andern Last, so werdet ihr das Gesetz Christi erfüllen.","lehrtextReference":"Galater 6,2"},"2026-10-18":{"text":"Ich will Frieden geben an dieser Stätte, spricht der HERR Zebaoth.","reference":"Haggai 2,9","translation":"Losung","lehrtext":"Jesus sprach zu ihnen: Steht nicht geschrieben: Mein Haus wird ein Bethaus heißen für alle Völker?","lehrtextReference":"Markus 11,17"},"2026-10-19":{"text":"Des Priesters Lippen sollen die Lehre bewahren, dass man aus seinem Munde Weisung suche; denn er ist ein Bote des HERRN Zebaoth.","reference":"Maleachi 2,7","translation":"Losung","lehrtext":"Verkündige das Wort, tritt dafür ein, zur Zeit oder Unzeit, widerlege, tadle, bitte, in aller Geduld, wo die Lehre es gebietet!","lehrtextReference":"2. Timotheus 4,2"},"2026-10-20":{"text":"Sie haben sich Götter von Gold gemacht. Vergib ihnen doch ihre Sünde!","reference":"2. Mose 32,31.32","translation":"Losung","lehrtext":"/Paulus sprach:/ Ich bin umhergegangen und habe eure Heiligtümer angesehen und fand einen Altar, auf dem stand geschrieben: Dem unbekannten Gott. Nun verkündige ich euch, was ihr unwissend verehrt.","lehrtextReference":"Apostelgeschichte 17,23"},"2026-10-21":{"text":"Der HERR wird dich immerdar führen und dich sättigen in der Dürre.","reference":"Jesaja 58,11","translation":"Losung","lehrtext":"Unser tägliches Brot gib uns heute.","lehrtextReference":"Matthäus 6,11"},"2026-10-22":{"text":"Der HERR hat uns gemacht und nicht wir selbst zu seinem Volk und zu Schafen seiner Weide.","reference":"Psalm 100,3","translation":"Losung","lehrtext":"/Jesus Christus spricht:/ Ich bin der gute Hirte und kenne die Meinen und die Meinen kennen mich.","lehrtextReference":"Johannes 10,14"},"2026-10-23":{"text":"Siehe, es kommt die Zeit, spricht der HERR, dass ich dem David einen gerechten Spross erwecken will. Der soll ein König sein, der wohl regieren und Recht und Gerechtigkeit im Lande üben wird.","reference":"Jeremia 23,5","translation":"Losung","lehrtext":"Simon Petrus sprach: Du bist der Christus, des lebendigen Gottes Sohn!","lehrtextReference":"Matthäus 16,16"},"2026-10-24":{"text":"Der HERR hat offenbart seinen heiligen Arm vor den Augen aller Völker, dass aller Welt Enden sehen das Heil unsres Gottes.","reference":"Jesaja 52,10","translation":"Losung","lehrtext":"Ihr seid also nicht mehr Fremde ohne Bürgerrecht, ihr seid vielmehr Mitbürger der Heiligen und Hausgenossen Gottes.","lehrtextReference":"Epheser 2,19"},"2026-10-25":{"text":"Gott, deine Güte ist besser als Leben.","reference":"Psalm 63,4","translation":"Losung","lehrtext":"Der Vater hat uns errettet aus der Macht der Finsternis und hat uns versetzt in das Reich seines geliebten Sohnes.","lehrtextReference":"Kolosser 1,13"},"2026-10-26":{"text":"Aber mit dir will ich nicht ein Ende machen. Ich will dich mit Maßen züchtigen, doch ungestraft kann ich dich nicht lassen.","reference":"Jeremia 30,11","translation":"Losung","lehrtext":"Weißt du nicht, dass Gottes Güte dich zur Umkehr leitet?","lehrtextReference":"Römer 2,4"},"2026-10-27":{"text":"Steh auf, Gott, richte die Erde, denn dein Eigentum sind die Nationen alle.","reference":"Psalm 82,8","translation":"Losung","lehrtext":"/Petrus sprach:/ Nun erfahre ich in Wahrheit, dass Gott die Person nicht ansieht; sondern in jedem Volk, wer ihn fürchtet und Recht tut, der ist ihm angenehm.","lehrtextReference":"Apostelgeschichte 10,34-35"},"2026-10-28":{"text":"Lobe den HERRN, der dein Leben vom Verderben erlöst, der dich krönet mit Gnade und Barmherzigkeit.","reference":"Psalm 103,2.4","translation":"Losung","lehrtext":"Jesus sprach zu ihr: Frau, du bist erlöst von deiner Krankheit! Und legte die Hände auf sie; und sogleich richtete sie sich auf und pries Gott.","lehrtextReference":"Lukas 13,12-13"},"2026-10-29":{"text":"Samuel sprach zu Saul: Du aber steh jetzt still, dass ich dir kundtue, was Gott gesagt hat.","reference":"1. Samuel 9,27","translation":"Losung","lehrtext":"Jesus sprach zu Simon und Andreas: Kommt, folgt mir nach; ich will euch zu Menschenfischern machen!","lehrtextReference":"Markus 1,17"},"2026-10-30":{"text":"Der HERR hebt auf den Dürftigen aus dem Staub.","reference":"1. Samuel 2,8","translation":"Losung","lehrtext":"Maria sprach: Meine Seele erhebt den Herrn, und mein Geist freuet sich Gottes, meines Heilandes; denn er hat die Niedrigkeit seiner Magd angesehen.","lehrtextReference":"Lukas 1,46-48"},"2026-10-31":{"text":"Unrecht Gut hilft nicht; aber Gerechtigkeit errettet vom Tode.","reference":"Sprüche 10,2","translation":"Losung","lehrtext":"Alle, die glauben, werden ohne Verdienst gerecht aus seiner Gnade durch die Erlösung, die durch Christus Jesus geschehen ist.","lehrtextReference":"Römer 3,24"},"2026-11-01":{"text":"Er wird herrlich werden bis an die Enden der Erde.","reference":"Micha 5,3","translation":"Losung","lehrtext":"/Jesus sprach:/ Ihr werdet meine Zeugen sein in Jerusalem und in ganz Judäa und Samarien und bis an das Ende der Erde.","lehrtextReference":"Apostelgeschichte 1,8"},"2026-11-02":{"text":"Der HERR wird richten die Völker.","reference":"Psalm 7,9","translation":"Losung","lehrtext":"Gott hat einen Tag festgesetzt, an dem er den Erdkreis richten wird in Gerechtigkeit durch einen Mann, den er dazu bestimmt hat, indem er ihn vor allen Menschen beglaubigte durch die Auferstehung von den Toten.","lehrtextReference":"Apostelgeschichte 17,31"},"2026-11-03":{"text":"Weißt du nicht? Hast du nicht gehört? Der HERR, der ewige Gott, der die Enden der Erde geschaffen hat, wird nicht müde noch matt, sein Verstand ist unausforschlich.","reference":"Jesaja 40,28","translation":"Losung","lehrtext":"Denn von ihm und durch ihn und zu ihm sind alle Dinge. Ihm sei Ehre in Ewigkeit! Amen.","lehrtextReference":"Römer 11,36"},"2026-11-04":{"text":"Der HERR wird Zion wieder trösten.","reference":"Sacharja 1,17","translation":"Losung","lehrtext":"/Jesus Christus spricht:/ Ihr habt nun Traurigkeit; aber ich will euch wiedersehen, und euer Herz soll sich freuen, und eure Freude soll niemand von euch nehmen.","lehrtextReference":"Johannes 16,22"},"2026-11-05":{"text":"Er wird auftreten und sie weiden in der Kraft des HERRN.","reference":"Micha 5,3","translation":"Losung","lehrtext":"/Jesus Christus spricht:/ Niemand wird meine Schafe aus meiner Hand reißen.","lehrtextReference":"Johannes 10,28"},"2026-11-06":{"text":"Brich dem Hungrigen dein Brot!","reference":"Jesaja 58,7","translation":"Losung","lehrtext":"Ich bin hungrig gewesen und ihr habt mir zu essen gegeben.","lehrtextReference":"Matthäus 25,35"},"2026-11-07":{"text":"Du machst Winde zu deinen Boten und Feuerflammen zu deinen Dienern.","reference":"Psalm 104,4","translation":"Losung","lehrtext":"Es geschah ein großes Erdbeben. Denn ein Engel des Herrn kam vom Himmel herab, trat hinzu und wälzte den Stein weg und setzte sich darauf.","lehrtextReference":"Matthäus 28,2"},"2026-11-08":{"text":"Abram sprach zu Lot: Es soll kein Zank sein zwischen mir und dir und zwischen meinen und deinen Hirten; denn wir sind Brüder.","reference":"1. Mose 13,8","translation":"Losung","lehrtext":"Seid darauf bedacht, zu wahren die Einigkeit im Geist durch das Band des Friedens.","lehrtextReference":"Epheser 4,3"},"2026-11-09":{"text":"Unsre Missetaten stellst du vor dich, unsre unerkannte Sünde ins Licht vor deinem Angesicht.","reference":"Psalm 90,8","translation":"Losung","lehrtext":"Wenn uns unser Herz verdammt, ist Gott größer als unser Herz und erkennt alle Dinge.","lehrtextReference":"1. Johannes 3,20"},"2026-11-10":{"text":"Seid getrost und unverzagt alle, die ihr des HERRN harret!","reference":"Psalm 31,25","translation":"Losung","lehrtext":"Die Jünger wurden erfüllt von Freude und Heiligem Geist.","lehrtextReference":"Apostelgeschichte 13,52"},"2026-11-11":{"text":"Ich will auf den HERRN schauen und harren auf den Gott meines Heils; mein Gott wird mich erhören.","reference":"Micha 7,7","translation":"Losung","lehrtext":"/Jesus spricht:/ Wer da bittet, der empfängt; und wer da sucht, der findet; und wer da anklopft, dem wird aufgetan.","lehrtextReference":"Matthäus 7,8"},"2026-11-12":{"text":"Gib acht auf deine Füße, wenn du zum Hause Gottes gehst. Und tritt hinzu, um zu hören.","reference":"Prediger 4,17","translation":"Losung","lehrtext":"Geh zuerst hin und versöhne dich mit deinem Bruder, und dann komm und opfere deine Gabe.","lehrtextReference":"Matthäus 5,24"},"2026-11-13":{"text":"Lass deine Augen offen stehen über diesem Hause Nacht und Tag, über der Stätte, von der du gesagt hast: Da soll mein Name sein.","reference":"1. Könige 8,29","translation":"Losung","lehrtext":"Jesus sagte zu seinen Eltern: Warum habt ihr mich gesucht? Wusstet ihr nicht, dass ich im Haus meines Vaters sein muss?","lehrtextReference":"Lukas 2,49"},"2026-11-14":{"text":"Der HERR, unser Gott, sei mit uns, wie er mit unseren Vorfahren war.","reference":"1. Könige 8,57","translation":"Losung","lehrtext":"/Paulus sprach:/ Wir verkündigen euch die Verheißung, die an die Väter ergangen ist, dass Gott sie uns, ihren Kindern, erfüllt hat, indem er Jesus auferweckte.","lehrtextReference":"Apostelgeschichte 13,32-33"},"2026-11-15":{"text":"Sie sollen sicher wohnen, und niemand soll sie schrecken.","reference":"Hesekiel 34,28","translation":"Losung","lehrtext":"Die Pforten der Hölle sollen meine Gemeinde nicht überwältigen.","lehrtextReference":"Matthäus 16,18"},"2026-11-16":{"text":"HERR, wer sollte dich nicht fürchten, du König der Völker? Dir muss man gehorchen.","reference":"Jeremia 10,7","translation":"Losung","lehrtext":"/Hananias sagte zu Paulus:/ Der Gott unserer Vorfahren hat dich dazu bestimmt, seinen Willen zu erkennen. Du durftest den Gerechten sehen und seine Stimme hören. Denn du wirst als Zeuge für ihn auftreten. Dann wirst du allen Menschen weitersagen, was du gesehen und gehört hast.","lehrtextReference":"Apostelgeschichte 22,14-15"},"2026-11-17":{"text":"Er hat die Sünde vieler getragen, und für die Übeltäter trat er ein.","reference":"Jesaja 53,12","translation":"Losung","lehrtext":"Johannes sieht, dass Jesus zu ihm kommt, und spricht: Siehe, das ist Gottes Lamm, das der Welt Sünde trägt!","lehrtextReference":"Johannes 1,29"},"2026-11-18":{"text":"Herzlich lieb habe ich dich, HERR, meine Stärke!","reference":"Psalm 18,2","translation":"Losung","lehrtext":"/Jesus sagte über die Sünderin:/ Ihre vielen Sünden sind vergeben, denn sie hat viel geliebt; wem aber wenig vergeben wird, der liebt wenig.","lehrtextReference":"Lukas 7,47"},"2026-11-19":{"text":"Ich will sie retten von allen ihren Abwegen, auf denen sie gesündigt haben, und will sie reinigen, und sie sollen mein Volk sein.","reference":"Hesekiel 37,23","translation":"Losung","lehrtext":"Gott, der reich ist an Barmherzigkeit, hat in seiner großen Liebe, mit der er uns geliebt hat, auch uns, die wir tot waren in den Sünden, mit Christus lebendig gemacht.","lehrtextReference":"Epheser 2,4-5"},"2026-11-20":{"text":"/Der HERR sprach zu Mose:/ Geh hin: Ich will mit deinem Munde sein und dich lehren, was du sagen sollst.","reference":"2. Mose 4,12","translation":"Losung","lehrtext":"/Jesus sprach zu Simon Petrus:/ Ich habe für dich gebeten, dass dein Glaube nicht aufhöre. Und wenn du dann umkehrst, so stärke deine Brüder.","lehrtextReference":"Lukas 22,32"},"2026-11-21":{"text":"Mein Wort wird nicht wieder leer zu mir zurückkommen, sondern wird tun, was mir gefällt, und ihm wird gelingen, wozu ich es sende.","reference":"Jesaja 55,11","translation":"Losung","lehrtext":"Das Wort Gottes ist lebendig und kräftig und schärfer als jedes zweischneidige Schwert und dringt durch, bis es scheidet Seele und Geist, auch Mark und Bein, und ist ein Richter der Gedanken und Sinne des Herzens.","lehrtextReference":"Hebräer 4,12"},"2026-11-22":{"text":"Gleichwie der Regen und Schnee vom Himmel fällt und nicht wieder dahin zurückkehrt, sondern feuchtet die Erde und macht sie fruchtbar und lässt wachsen, dass sie gibt Samen zu säen und Brot zu essen, so soll das Wort, das aus meinem Munde geht, auch sein.","reference":"Jesaja 55,10-11","translation":"Losung","lehrtext":"Das auf dem guten Land sind die, die das Wort hören und behalten in einem feinen, guten Herzen und bringen Frucht in Geduld.","lehrtextReference":"Lukas 8,15"},"2026-11-23":{"text":"HERR, du bist’s allein, du hast gemacht den Himmel und aller Himmel Himmel mit ihrem ganzen Heer, die Erde und alles, was darauf ist, die Meere und alles, was darinnen ist.","reference":"Nehemia 9,6","translation":"Losung","lehrtext":"Jedes Geschöpf im Himmel und auf der Erde und unter der Erde und auf dem Meer, und alles, was darin ist, hörte ich rufen: Ihm, der auf dem Thron sitzt, und dem Lamm seien Lob, Ehre und Preis und die Herrschaft, von Ewigkeit zu Ewigkeit.","lehrtextReference":"Offenbarung 5,13"},"2026-11-24":{"text":"Du sollst der Menge nicht auf dem Weg zum Bösen folgen.","reference":"2. Mose 23,2","translation":"Losung","lehrtext":"Segnet, die euch verfolgen; segnet, und verflucht sie nicht.","lehrtextReference":"Römer 12,14"},"2026-11-25":{"text":"Ich wandle in weitem Raum; denn ich suche deine Befehle.","reference":"Psalm 119,45","translation":"Losung","lehrtext":"/Jesus spricht:/ Das ist mein Gebot, dass ihr euch untereinander liebt, wie ich euch liebe.","lehrtextReference":"Johannes 15,12"},"2026-11-26":{"text":"Hiskia wurde todkrank; und er betete zum HERRN. Der redete mit ihm und gab ihm ein Wunderzeichen. Aber Hiskia vergalt nicht nach dem, was ihm geschehen war; denn sein Herz überhob sich.","reference":"2. Chronik 32,24-25","translation":"Losung","lehrtext":"Hört nicht auf, Gott zu danken.","lehrtextReference":"Kolosser 2,7"},"2026-11-27":{"text":"Du, HERR, bist meine Leuchte; der HERR macht meine Finsternis licht.","reference":"2. Samuel 22,29","translation":"Losung","lehrtext":"In ihm war das Leben, und das Leben war das Licht der Menschen.","lehrtextReference":"Johannes 1,4"},"2026-11-28":{"text":"Wie lieblich sind auf den Bergen die Füße des Freudenboten, der da Frieden verkündigt, Gutes predigt, Heil verkündigt, der da sagt zu Zion: Dein Gott ist König!","reference":"Jesaja 52,7","translation":"Losung","lehrtext":"Ehre sei Gott in der Höhe und Friede auf Erden bei den Menschen seines Wohlgefallens.","lehrtextReference":"Lukas 2,14"},"2026-11-29":{"text":"Jonatan ging hin zu David und stärkte sein Vertrauen auf Gott.","reference":"1. Samuel 23,16","translation":"Losung","lehrtext":"Tröstet euch untereinander und einer erbaue den andern, wie ihr auch tut.","lehrtextReference":"1. Thessalonicher 5,11"},"2026-11-30":{"text":"Der Storch unter dem Himmel weiß seine Zeit, Turteltaube, Schwalbe und Drossel halten die Zeit ein, in der sie wiederkommen sollen; aber mein Volk will das Recht des HERRN nicht wissen.","reference":"Jeremia 8,7","translation":"Losung","lehrtext":"Umso fester haben wir das prophetische Wort, und ihr tut gut daran, dass ihr darauf achtet als auf ein Licht, das da scheint an einem dunklen Ort, bis der Tag anbricht und der Morgenstern aufgeht in euren Herzen.","lehrtextReference":"2. Petrus 1,19"},"2026-12-01":{"text":"Kehrt zurück, ihr abtrünnigen Kinder, so will ich euch heilen von eurem Ungehorsam. »Siehe, wir kommen zu dir; denn du bist der HERR, unser Gott.«","reference":"Jeremia 3,22","translation":"Losung","lehrtext":"/Jesus spricht:/ So, sage ich euch, ist Freude vor den Engeln Gottes über einen Sünder, der Buße tut.","lehrtextReference":"Lukas 15,10"},"2026-12-02":{"text":"Neigt eure Ohren her und kommt her zu mir! Höret, so werdet ihr leben!","reference":"Jesaja 55,3","translation":"Losung","lehrtext":"Darum sollen wir desto mehr achten auf das Wort, das wir hören, damit wir nicht am Ziel vorbeitreiben.","lehrtextReference":"Hebräer 2,1"},"2026-12-03":{"text":"Ich habe dich bereitet, dass du mein Knecht seist. Israel, ich vergesse dich nicht!","reference":"Jesaja 44,21","translation":"Losung","lehrtext":"Abraham wusste aufs Allergewisseste: Was Gott verheißt, das kann er auch tun.","lehrtextReference":"Römer 4,21"},"2026-12-04":{"text":"Die da sitzen mussten in Finsternis und Dunkel, gefangen in Zwang und Eisen, die dann zum HERRN riefen in ihrer Not und er half ihnen aus ihren Ängsten: Die sollen dem HERRN danken für seine Güte und für seine Wunder, die er an den Menschenkindern tut.","reference":"Psalm 107,10.13.15","translation":"Losung","lehrtext":"Durch die herzliche Barmherzigkeit unseres Gottes wird uns besuchen das aufgehende Licht aus der Höhe, auf dass es erscheine denen, die sitzen in Finsternis und Schatten des Todes, und richte unsere Füße auf den Weg des Friedens.","lehrtextReference":"Lukas 1,78-79"},"2026-12-05":{"text":"Ich bin der Erste, und ich bin der Letzte, und außer mir ist kein Gott.","reference":"Jesaja 44,6","translation":"Losung","lehrtext":"Jesus Christus gestern und heute und derselbe auch in Ewigkeit.","lehrtextReference":"Hebräer 13,8"},"2026-12-06":{"text":"Wer Dank opfert, der preiset mich, und da ist der Weg, dass ich ihm zeige das Heil Gottes.","reference":"Psalm 50,23","translation":"Losung","lehrtext":"Dankt dem Vater mit Freude! Er hat euch fähig gemacht, Anteil zu haben am Erbe der Heiligen, die im Licht leben.","lehrtextReference":"Kolosser 1,12"},"2026-12-07":{"text":"In Gottes Hand sind die Tiefen der Erde, und die Höhen der Berge sind auch sein.","reference":"Psalm 95,4","translation":"Losung","lehrtext":"Auch die Schöpfung wird frei werden von der Knechtschaft der Vergänglichkeit zu der herrlichen Freiheit der Kinder Gottes.","lehrtextReference":"Römer 8,21"},"2026-12-08":{"text":"Singet dem HERRN und lobet seinen Namen, verkündet von Tag zu Tag sein Heil!","reference":"Psalm 96,2","translation":"Losung","lehrtext":"Bringt euren Leib dar als lebendiges, heiliges, Gott wohlgefälliges Opfer - dies sei euer vernünftiger Gottesdienst!","lehrtextReference":"Römer 12,1"},"2026-12-09":{"text":"Der Gerechte ist wie ein Baum, gepflanzt an den Wasserbächen, der seine Frucht bringt zu seiner Zeit, und seine Blätter verwelken nicht.","reference":"Psalm 1,3","translation":"Losung","lehrtext":"/Jesus Christus spricht:/ Bleibt in mir und ich in euch. Wie die Rebe keine Frucht bringen kann aus sich selbst, wenn sie nicht am Weinstock bleibt, so auch ihr nicht, wenn ihr nicht an mir bleibt.","lehrtextReference":"Johannes 15,4"},"2026-12-10":{"text":"Kommt her, höret zu alle, die ihr Gott fürchtet; ich will erzählen, was er an mir getan hat.","reference":"Psalm 66,16","translation":"Losung","lehrtext":"/Maria sprach:/ Siehe, von nun an werden mich selig preisen alle Kindeskinder. Denn er hat große Dinge an mir getan, der da mächtig ist und dessen Name heilig ist.","lehrtextReference":"Lukas 1,48-49"},"2026-12-11":{"text":"Siehe, es ist kein Wort auf meiner Zunge, das du, HERR, nicht alles wüsstest.","reference":"Psalm 139,4","translation":"Losung","lehrtext":"Kein Geschöpf ist vor ihm verborgen, sondern es ist alles bloß und aufgedeckt vor den Augen dessen, dem wir Rechenschaft geben müssen.","lehrtextReference":"Hebräer 4,13"},"2026-12-12":{"text":"HERR, schone dein Volk und lass dein Erbteil nicht zuschanden werden!","reference":"Joel 2,17","translation":"Losung","lehrtext":"Sie sind Israeliten, denen die Kindschaft gehört und die Herrlichkeit und die Bundesschlüsse und das Gesetz und der Gottesdienst und die Verheißungen.","lehrtextReference":"Römer 9,4"},"2026-12-13":{"text":"Die Frau nahm von der Frucht und aß und gab ihrem Mann, der bei ihr war, auch davon und er aß.","reference":"1. Mose 3,6","translation":"Losung","lehrtext":"Die Welt vergeht, mit ihrem Begehren; wer aber den Willen Gottes tut, der bleibt in Ewigkeit.","lehrtextReference":"1. Johannes 2,17"},"2026-12-14":{"text":"Weh den törichten Propheten, die ihrem eigenen Geist folgen und nichts geschaut haben!","reference":"Hesekiel 13,3","translation":"Losung","lehrtext":"Jesus sprach: Viele werden kommen unter meinem Namen und sagen: Ich bin’s, und: Die Zeit ist herbeigekommen. – Lauft ihnen nicht nach!","lehrtextReference":"Lukas 21,8"},"2026-12-15":{"text":"Wasche dein Herz von der Bosheit, auf dass dir geholfen werde. Wie lange wollen bei dir bleiben deine heillosen Gedanken?","reference":"Jeremia 4,14","translation":"Losung","lehrtext":"Vergib uns unsre Sünden; denn auch wir vergeben jedem, der an uns schuldig wird.","lehrtextReference":"Lukas 11,4"},"2026-12-16":{"text":"Du sollst deinen Bruder nicht hassen in deinem Herzen, sondern du sollst deinen Nächsten zurechtweisen, damit du nicht seinetwegen Schuld auf dich lädst.","reference":"3. Mose 19,17","translation":"Losung","lehrtext":"Brüder und Schwestern, freut euch, lasst euch zurechtbringen, lasst euch mahnen, habt einerlei Sinn, haltet Frieden!","lehrtextReference":"2. Korinther 13,11"},"2026-12-17":{"text":"Wenn ich auch noch so viele meiner Gebote aufschreibe, so werden sie doch geachtet wie eine fremde Lehre.","reference":"Hosea 8,12","translation":"Losung","lehrtext":"Was zuvor geschrieben ist, das ist uns zur Lehre geschrieben, damit wir durch Geduld und den Trost der Schrift Hoffnung haben.","lehrtextReference":"Römer 15,4"},"2026-12-18":{"text":"Aus der Tiefe rufe ich, HERR, zu dir. Herr, höre meine Stimme!","reference":"Psalm 130,1-2","translation":"Losung","lehrtext":"Es kam eine große Menge zu Jesus; die hatten bei sich Lahme, Blinde, Verkrüppelte, Stumme und viele andere und legten sie ihm vor die Füße, und er heilte sie.","lehrtextReference":"Matthäus 15,30"},"2026-12-19":{"text":"Dir, HERR, ist niemand gleich; du bist groß, und dein Name ist groß, wie du es mit der Tat beweist.","reference":"Jeremia 10,6","translation":"Losung","lehrtext":"Bei Gott ist kein Ding unmöglich.","lehrtextReference":"Lukas 1,37"},"2026-12-20":{"text":"Dennoch soll die Stadt Gottes fein lustig bleiben mit ihren Brünnlein, da die heiligen Wohnungen des Höchsten sind. Gott ist bei ihr drinnen, darum wird sie fest bleiben.","reference":"Psalm 46,5-6","translation":"Losung","lehrtext":"Und die Völker werden wandeln in ihrem Licht; und die Könige auf Erden werden ihre Herrlichkeit in sie bringen.","lehrtextReference":"Offenbarung 21,24"},"2026-12-21":{"text":"Du führst, Herr, meine Sache und erlöst mein Leben.","reference":"Klagelieder 3,58","translation":"Losung","lehrtext":"Stephanus rief den Herrn an und sprach: Herr Jesus, nimm meinen Geist auf!","lehrtextReference":"Apostelgeschichte 7,59"},"2026-12-22":{"text":"Der HERR mehre euch, euch und eure Kinder!","reference":"Psalm 115,14","translation":"Losung","lehrtext":"/Elisabeth sprach zu Maria:/ Gesegnet bist du unter den Frauen, und gesegnet ist die Frucht deines Leibes!","lehrtextReference":"Lukas 1,42"},"2026-12-23":{"text":"Gott schuf den Menschen zu seinem Bilde, zum Bilde Gottes schuf er ihn und schuf sie als Mann und Frau.","reference":"1. Mose 1,27","translation":"Losung","lehrtext":"Im Herrn ist weder die Frau etwas ohne den Mann noch ist der Mann etwas ohne die Frau. Denn wie die Frau vom Mann stammt, so ist der Mann durch die Frau; alles aber kommt von Gott.","lehrtextReference":"1. Korinther 11,11-12"},"2026-12-24":{"text":"HERR, du bist unser Gott, gegen dich vermag kein Mensch etwas.","reference":"2. Chronik 14,10","translation":"Losung","lehrtext":"Wir haben gesehen und bezeugen, dass der Vater den Sohn gesandt hat als Heiland der Welt.","lehrtextReference":"1. Johannes 4,14"},"2026-12-25":{"text":"Dein Wort ist meines Fußes Leuchte und ein Licht auf meinem Wege.","reference":"Psalm 119,105","translation":"Losung","lehrtext":"Und da die Engel von ihnen gen Himmel fuhren, sprachen die Hirten untereinander: Lasst uns nun gehen gen Bethlehem und die Geschichte sehen, die da geschehen ist, die uns der Herr kundgetan hat.","lehrtextReference":"Lukas 2,15"},"2026-12-26":{"text":"Ich will wachen über meinem Wort, dass ich’s tue.","reference":"Jeremia 1,12","translation":"Losung","lehrtext":"Als aber die Zeit erfüllt war, sandte Gott seinen Sohn, geboren von einer Frau und unter das Gesetz getan, auf dass er die, die unter dem Gesetz waren, loskaufte, damit wir die Kindschaft empfingen.","lehrtextReference":"Galater 4,4-5"},"2026-12-27":{"text":"Wohl dem, dem die Übertretungen vergeben sind, dem die Sünde bedeckt ist!","reference":"Psalm 32,1","translation":"Losung","lehrtext":"In Jesus Christus haben wir die Erlösung durch sein Blut, die Vergebung der Sünden, nach dem Reichtum seiner Gnade.","lehrtextReference":"Epheser 1,7"},"2026-12-28":{"text":"Boas sprach zu den Schnittern: Der HERR sei mit euch! Sie antworteten: Der HERR segne dich!","reference":"Rut 2,4","translation":"Losung","lehrtext":"Friede sei mit den Brüdern und Schwestern und Liebe mit Glauben von Gott, dem Vater, und dem Herrn Jesus Christus!","lehrtextReference":"Epheser 6,23"},"2026-12-29":{"text":"Gott, du kennst meine Torheit, und meine Schuld ist dir nicht verborgen.","reference":"Psalm 69,6","translation":"Losung","lehrtext":"Spricht Jesus zum dritten Mal zu ihm: Simon, Sohn des Johannes, hast du mich lieb? Petrus wurde traurig, weil er zum dritten Mal zu ihm sagte: Hast du mich lieb?, und sprach zu ihm: Herr, du weißt alle Dinge, du weißt, dass ich dich lieb habe.","lehrtextReference":"Johannes 21,17"},"2026-12-30":{"text":"Halte dich ferne von einer Sache, bei der Lüge im Spiel ist.","reference":"2. Mose 23,7","translation":"Losung","lehrtext":"Brüder und Schwestern: Was wahrhaftig ist, was ehrbar, was gerecht, was rein, was liebenswert, was einen guten Ruf hat, sei es eine Tugend, sei es ein Lob – darauf seid bedacht!","lehrtextReference":"Philipper 4,8"},"2026-12-31":{"text":"So halte nun die Gebote des HERRN, deines Gottes, dass du in seinen Wegen wandelst und ihn fürchtest.","reference":"5. Mose 8,6","translation":"Losung","lehrtext":"/Jesus spricht:/ Wer den Willen tut meines Vaters im Himmel, der ist mir Bruder und Schwester und Mutter.","lehrtextReference":"Matthäus 12,50"}};
